export const PHOTO_ART_BANK: QuestionBank = {
  curriculumId: 'photo-art-school',
  questions: [
    {"id":"photo-art-school.px-1.q1","lessonId":"px-1","kind":"mcq","prompt":"Which three controls govern how much light lands on the recording surface?","choices":["Shutter speed, metering and focus","ISO, resolution and lens coating","Aperture, shutter speed and ISO","Focal length, aperture and white balance"],"answer":2,"hint":"Think hole size, time, and sensitivity.","explanation":"The lesson names aperture (size of the hole), shutter speed (how long it stays open) and ISO (how strongly the surface reacts) as the three light controls.","level":1},
    {"id":"photo-art-school.px-1.q2","lessonId":"px-1","kind":"mcq","prompt":"You want a landscape sharp from foreground rock to distant mountain. Which of the three controls are you mainly spending?","choices":["Aperture, giving up light per moment for depth of field","None of them; they are independent of the picture","ISO, giving up cleanliness for motion","Shutter speed, giving up motion for noise"],"answer":0,"hint":"Which control buys depth of field?","explanation":"Aperture buys depth of field; a small opening gives deep focus but passes less light, so you must compensate elsewhere.","level":2},
    {"id":"photo-art-school.px-1.q3","lessonId":"px-1","kind":"tf","prompt":"According to the lesson, a correct exposure is whatever number the camera meter calculates.","answer":1,"hint":"Who decides what the picture should look like?","explanation":"The lesson says correct exposure is the brightness that serves the picture you intend, and the meter is only a suggestion from a machine that cannot see your subject.","level":3},
    {"id":"photo-art-school.px-2.q1","lessonId":"px-2","kind":"mcq","prompt":"What is an f-number a ratio of?","choices":["Focus distance divided by the size of the subject in frame","Shutter time divided by ISO","Sensor width divided by lens length","Focal length divided by the diameter of the opening"],"answer":3,"hint":"It is why larger numbers mean smaller holes.","explanation":"The f-number is focal length divided by aperture diameter, so a bigger number means a smaller opening.","level":1},
    {"id":"photo-art-school.px-2.q2","lessonId":"px-2","kind":"mcq","prompt":"You are shooting a portrait and want only the eyes sharp with the ears dissolving. Which aperture is the best choice?","choices":["f/8, for a balanced middle depth","f/1.4","f/16, for maximum depth of field","f/11, the sharpest aperture on most lenses"],"answer":1,"hint":"You want a very thin band of sharpness.","explanation":"Wide open, such as f/1.4, gives millimetre-thin depth of field; f/11 and f/16 hold much more of the scene sharp.","level":2},
    {"id":"photo-art-school.px-2.q3","lessonId":"px-2","kind":"mcq","prompt":"Why does the lesson advise against shooting everything wide open?","choices":["Wide-open lenses cannot focus","Depth of field is a way of saying something, and always using shallow depth repeats one sentence","Wide apertures overexpose every image","Diffraction is worst at wide apertures"],"answer":1,"hint":"The lesson compares depth of field to sentence structure.","explanation":"Shallow depth says only this matters; deep depth says everything and its relationships. Using one always repeats one statement.","level":3},
    {"id":"photo-art-school.px-3.q1","lessonId":"px-3","kind":"mcq","prompt":"By the reciprocal rule, what is the slowest recommended hand-held shutter speed for a 200mm lens?","choices":["1/60s","1/30s","1/2000s","1/200s"],"answer":3,"hint":"One over the focal length.","explanation":"The reciprocal rule says hand-hold no slower than one over the focal length, so 200mm wants 1/200s or faster.","level":1},
    {"id":"photo-art-school.px-3.q2","lessonId":"px-3","kind":"mcq","prompt":"You want a river to look like silk and a crowd to turn into ghosts. What do you do?","choices":["Use a slow shutter speed such as two seconds, ideally on a stable support","Use a very fast shutter speed such as 1/4000s","Raise ISO as high as possible","Use the reciprocal rule for the focal length"],"answer":0,"hint":"Only stationary parts deposit consistently.","explanation":"A slow exposure accumulates, so only the stationary parts of the scene register consistently while moving elements smear.","level":2},
    {"id":"photo-art-school.px-3.q3","lessonId":"px-3","kind":"mcq","prompt":"Why does image stabilisation not solve every blur problem?","choices":["It replaces the need for shutter speed","It only works in bright light","It stabilises your hands, not a moving subject","It adds subject blur deliberately"],"answer":2,"hint":"Two separate blurs exist.","explanation":"Stabilisation compensates for camera shake but cannot freeze a subject that moves during the exposure.","level":3},
    {"id":"photo-art-school.px-4.q1","lessonId":"px-4","kind":"mcq","prompt":"What does raising ISO actually do, according to the lesson?","choices":["Collects more light","Makes the lens aperture larger","Slows the shutter automatically","Amplifies the signal already collected, noise included"],"answer":3,"hint":"Think volume knob.","explanation":"ISO amplifies the signal off the sensor; it does not collect more light, and noise rises with it.","level":1},
    {"id":"photo-art-school.px-4.q2","lessonId":"px-4","kind":"mcq","prompt":"In low light you can either shoot underexposed at low ISO and brighten later, or expose properly at higher ISO. Following expose for the shadows you intend to keep, which is usually cleaner?","choices":["Underexpose, then push in editing","Expose brighter, then pull down in editing","Both are identical in noise","Switching to JPEG"],"answer":1,"hint":"Noise lives in the underexposed parts.","explanation":"A brighter capture pulled down is almost always cleaner than a dark one pushed up, since noise lives in underexposed regions.","level":2},
    {"id":"photo-art-school.px-4.q3","lessonId":"px-4","kind":"tf","prompt":"The lesson argues a sharp noisy photograph is better than a clean blurred one.","answer":0,"hint":"Grain is a texture; blur from timidity is a mistake.","explanation":"The lesson says a sharp noisy photograph beats a clean blurred one every time, so be willing to raise ISO.","level":3},
    {"id":"photo-art-school.px-5.q1","lessonId":"px-5","kind":"mcq","prompt":"Roughly what reflectance does a reflective meter assume the scene averages to?","choices":["18%","90%","5%","50%"],"answer":0,"hint":"Middle grey.","explanation":"Meters assume middle grey, about 18% reflectance.","level":1},
    {"id":"photo-art-school.px-5.q2","lessonId":"px-5","kind":"mcq","prompt":"You are photographing a snowy field and the camera renders the snow grey. What correction fixes it?","choices":["Lower ISO by two stops","Exposure compensation of about -2","Exposure compensation of about +1 to +2","Switch to spot metering and aim at a black object"],"answer":2,"hint":"The meter wants to make everything average.","explanation":"Snow fools the meter into underexposing, so you add +1 to +2 stops of compensation.","level":2},
    {"id":"photo-art-school.px-5.q3","lessonId":"px-5","kind":"mcq","prompt":"Why are blown highlights treated as worse than crushed shadows?","choices":["Shadows cannot be seen on the histogram","Histograms only show highlights","Clipped highlights contain no data and cannot be recovered, whereas shadows can often be lifted at the cost of noise","Highlights always look ugly"],"answer":2,"hint":"Think about what remains in the file.","explanation":"Pixels clipped at the white wall are gone, while crushed shadows can often be lifted although they become noisier.","level":3},
    {"id":"photo-art-school.px-6.q1","lessonId":"px-6","kind":"mcq","prompt":"On full-frame, which focal length range does the lesson call classic portraiture?","choices":["85-135mm","200mm and up","14-24mm","35mm"],"answer":0,"hint":"Short telephoto.","explanation":"The lesson lists 85-135mm as classic portraiture.","level":1},
    {"id":"photo-art-school.px-6.q2","lessonId":"px-6","kind":"mcq","prompt":"You shoot a face with a 24mm lens from one metre and a 200mm lens from eight metres, then compare. What explains the different look?","choices":["The wide lens bends space differently from the telephoto lens","The sensor size","Aperture differences","The change in where you stood, which alters perspective"],"answer":3,"hint":"Perspective depends on position alone.","explanation":"Perspective is determined by camera position; wide lenses make you step closer, exaggerating near-to-far size differences.","level":2},
    {"id":"photo-art-school.px-6.q3","lessonId":"px-6","kind":"mcq","prompt":"A 35mm lens on an APS-C camera frames like roughly what on full-frame?","choices":["24mm","52mm","35mm","85mm"],"answer":1,"hint":"The lesson gives the number.","explanation":"APS-C multiplies the effective angle, so 35mm frames like about 52mm; the sensor sees a smaller part of the image circle.","level":3},
    {"id":"photo-art-school.px-7.q1","lessonId":"px-7","kind":"mcq","prompt":"Which autofocus mode should you use for moving subjects?","choices":["Single (AF-S / One Shot), which locks once and holds","Continuous (AF-C / AI Servo)","Manual focus only, set once at the start of the sequence","Focus peaking, which highlights the sharpest edges in the view"],"answer":1,"hint":"One mode locks, the other tracks.","explanation":"Continuous AF tracks moving subjects; single AF locks and holds for stationary ones.","level":1},
    {"id":"photo-art-school.px-7.q2","lessonId":"px-7","kind":"mcq","prompt":"You are shooting through a chain-link fence and the camera keeps focusing on the wire. What does the lesson suggest?","choices":["Raise ISO","Use continuous AF with a wider aperture","Use RAW","Switch to manual focus"],"answer":3,"hint":"Autofocus grabs the nearest contrast.","explanation":"Shooting through obstructions is one of three situations where manual focus still wins, because AF grabs the fence.","level":2},
    {"id":"photo-art-school.px-7.q3","lessonId":"px-7","kind":"mcq","prompt":"What is the main advantage of back-button focus?","choices":["It separates focusing from the shutter release so you can recompose and never refocus accidentally at release","It increases depth of field","It disables eye-detection","It speeds up the shutter"],"answer":0,"hint":"Two buttons, two jobs.","explanation":"Assigning AF to a rear button means the shutter only fires, so you focus when you choose and recompose freely.","level":3},
    {"id":"photo-art-school.px-8.q1","lessonId":"px-8","kind":"mcq","prompt":"How does the lesson describe a RAW file compared with a JPEG?","choices":["They are identical in latitude","A RAW is always 8-bit","A RAW is the negative, with white balance stored as a note; a JPEG is a finished print","A RAW is a finished print; a JPEG is the negative"],"answer":2,"hint":"Negative versus print.","explanation":"The lesson says a JPEG is a finished print with settings baked in, while RAW is the unprocessed negative with white balance stored as a note.","level":1},
    {"id":"photo-art-school.px-8.q2","lessonId":"px-8","kind":"mcq","prompt":"You shot a series under tungsten light and the colour looks wrong. Which approach gives the cleanest fix after the fact?","choices":["Use a wider aperture","Shoot JPEG and change white balance later","Raise ISO","Shoot RAW and change white balance in editing"],"answer":3,"hint":"One format stores white balance as a note.","explanation":"RAW lets you change white balance after shooting with no penalty, which JPEG cannot do cleanly.","level":2},
    {"id":"photo-art-school.px-8.q3","lessonId":"px-8","kind":"tf","prompt":"An unprocessed RAW file looking flat and dull usually means something is wrong with the camera.","answer":1,"hint":"Think headroom.","explanation":"The lesson says RAW is meant to look flat; that is headroom for editing, not a fault.","level":3},
    {"id":"photo-art-school.pc-1.q1","lessonId":"pc-1","kind":"mcq","prompt":"Why does the lesson call photographic composition subtractive?","choices":["Photographs are always cropped","Photographers cut a rectangle from an infinite world, so the question is what to get rid of","Photographers remove colour in editing","Cameras subtract light"],"answer":1,"hint":"Compare to painting on an empty surface.","explanation":"Painters add to an empty surface, whereas photographers begin with the whole world and decide what to leave out.","level":1},
    {"id":"photo-art-school.pc-1.q2","lessonId":"pc-1","kind":"mcq","prompt":"Before pressing the shutter you spot a pole seeming to grow out of your subject head. What does the lesson say is usually the fix?","choices":["Moving a couple of feet","Raising ISO","Switching to square crop","Heavy retouching"],"answer":0,"hint":"The remedy is physical.","explanation":"These edge problems are all fixed by moving two feet, which is why you should scan the four borders.","level":2},
    {"id":"photo-art-school.pc-1.q3","lessonId":"pc-1","kind":"mcq","prompt":"Which aspect ratio does the lesson say removes any argument about direction and suits portraits and still life?","choices":["3:2","4:3","1:1","16:9"],"answer":2,"hint":"Equal sides.","explanation":"The square 1:1 frame forces the eye to the centre and removes directional arguments.","level":3},
    {"id":"photo-art-school.pc-2.q1","lessonId":"pc-2","kind":"mcq","prompt":"What two blandest options does the rule of thirds prevent?","choices":["Close-up and wide-angle framing, the two extremes of subject size","Portrait and landscape orientation, the two basic frame shapes","Dead centre and dead edge","Too bright and too dark, the two extremes of exposure"],"answer":2,"hint":"Think placement.","explanation":"Placing subjects near the third lines avoids dead centre and dead edge placements.","level":1},
    {"id":"photo-art-school.pc-2.q2","lessonId":"pc-2","kind":"mcq","prompt":"You want a formal, confrontational, monumental portrait. Which composition choice fits?","choices":["Centre the subject deliberately for symmetry","Shrink the subject into a corner with space around it","Use heavy negative space on the right","Place the subject on a third line"],"answer":0,"hint":"Symmetry carries a particular mood.","explanation":"The lesson says symmetry reads as formal, confrontational, monumental and still; a dead-centred portrait stares back at the viewer.","level":2},
    {"id":"photo-art-school.pc-2.q3","lessonId":"pc-2","kind":"mcq","prompt":"What does the lesson say is the real principle underneath both thirds and symmetry?","choices":["Keeping horizons perfectly level in every frame","Colour harmony across the whole frame","Using the golden ratio to place every subject","Balance of visual weight"],"answer":3,"hint":"The eye notices when weight pools in one corner.","explanation":"Both are ways of balancing the frame visual weight, which is more important than any grid.","level":3},
    {"id":"photo-art-school.pc-3.q1","lessonId":"pc-3","kind":"mcq","prompt":"In left-to-right reading cultures, where does the eye usually enter a photograph, according to the lesson?","choices":["Top-right","Bottom-left","Dead centre","Top-left"],"answer":1,"hint":"Think about the corner where reading starts at the bottom.","explanation":"The lesson says the eye usually enters bottom-left in left-to-right reading cultures.","level":1},
    {"id":"photo-art-school.pc-3.q2","lessonId":"pc-3","kind":"mcq","prompt":"You photograph a row of identical arches and want a story rather than mere pattern. What should you add?","choices":["A vignette that darkens the corners and draws the eye inward","One interruption, such as a single figure or broken element","More arches","A wider aperture"],"answer":1,"hint":"Repetition with variation.","explanation":"Pure repetition is decorative and static; repetition with one interruption becomes a story and the interruption becomes the subject.","level":2},
    {"id":"photo-art-school.pc-3.q3","lessonId":"pc-3","kind":"mcq","prompt":"Which shape does the lesson call the most stable arrangement of three subjects?","choices":["The horizontal line","The S-curve","The diagonal","The triangle"],"answer":3,"hint":"Think of Renaissance Madonnas.","explanation":"The triangle is the most stable arrangement and underpins most classical group portraits.","level":3},
    {"id":"photo-art-school.pc-4.q1","lessonId":"pc-4","kind":"mcq","prompt":"What are the three layers of a layered photograph?","choices":["Foreground, middle ground and background","Colour, shape and line","Sky, ground and subject","Highlights, mid-tones and shadows in the tonal range"],"answer":0,"hint":"Distance zones.","explanation":"A layered photograph has a foreground, middle ground and background, each carrying information.","level":1},
    {"id":"photo-art-school.pc-4.q2","lessonId":"pc-4","kind":"mcq","prompt":"You find a background with great light and a gesture. Following the lesson method, what do you do next?","choices":["Open the aperture to blur it","Add a flash","Frame it and wait for the foreground to arrive","Walk on"],"answer":2,"hint":"Patience.","explanation":"The method is to find a worthwhile background, frame it, then wait for a foreground element to converge.","level":2},
    {"id":"photo-art-school.pc-4.q3","lessonId":"pc-4","kind":"mcq","prompt":"What did Henri Cartier-Bresson decisive moment actually describe, per the lesson?","choices":["The fastest shutter speed","The first frame of a series","The peak of the action","The instant when form and content align"],"answer":3,"hint":"It is not just about action.","explanation":"The lesson says it is when the geometry of the frame and the meaning of the event become right together.","level":3},
    {"id":"photo-art-school.pc-5.q1","lessonId":"pc-5","kind":"mcq","prompt":"How does the lesson define negative space?","choices":["Black borders","The emptiness around a subject, treated as an active material","Leftover emptiness around a subject that should be cropped away","Underexposed areas"],"answer":1,"hint":"It is not leftover.","explanation":"Negative space is the emptiness around a subject and acts as a compositional material.","level":1},
    {"id":"photo-art-school.pc-5.q2","lessonId":"pc-5","kind":"mcq","prompt":"A cluttered background ruins your portrait. Which tactic from the lesson helps?","choices":["Crouch so the subject sits against sky","Add more subjects","Stop down to f/22","Use a longer exposure"],"answer":0,"hint":"Change height.","explanation":"Changing your height lets you place the subject against a simple background such as sky; opening the aperture also dissolves clutter.","level":2},
    {"id":"photo-art-school.pc-5.q3","lessonId":"pc-5","kind":"mcq","prompt":"The same small figure reads as solitude in a vast field of snow but as presence when filling the frame. What does this show?","choices":["Wide lenses distort","Snow is always lonely","The space around the subject shapes meaning","The figure changed"],"answer":2,"hint":"The subject stays the same.","explanation":"The subject did not change; the space did, showing negative space actively shapes meaning.","level":3},
    {"id":"photo-art-school.pc-6.q1","lessonId":"pc-6","kind":"mcq","prompt":"What happens when you lower the camera, per the lesson?","choices":["Nothing changes","The subject flattens into a pattern","The subject gains stature","The subject is hidden"],"answer":2,"hint":"You look up at it.","explanation":"Lowering the camera makes you look up at the subject, so it gains stature against sky.","level":1},
    {"id":"photo-art-school.pc-6.q2","lessonId":"pc-6","kind":"mcq","prompt":"You want viewers to identify with a figure, looking with them rather than at them. Which camera position fits?","choices":["From behind","Directly above","Face-on","Three-quarter"],"answer":0,"hint":"Think Caspar David Friedrich.","explanation":"The figure seen from behind creates identification, a staple from Friedrich onward.","level":2},
    {"id":"photo-art-school.pc-6.q3","lessonId":"pc-6","kind":"mcq","prompt":"Why do children and animals photographed from adult height look like specimens?","choices":["Lenses distort them","They move too fast","Light is poorer there","Adult eye-level is a default viewpoint looking down; their own eye level makes them look like people"],"answer":3,"hint":"Viewpoint is a choice.","explanation":"From above they are observed as specimens; at their own eye level they feel like people.","level":3},
    {"id":"photo-art-school.pc-7.q1","lessonId":"pc-7","kind":"mcq","prompt":"What does the lesson say photographers are usually read through?","choices":["Single frames","Series","Technical specifications","Camera brands"],"answer":1,"hint":"Bodies of work.","explanation":"Reputations are built through series: picture stories, essays, books and portfolios.","level":1},
    {"id":"photo-art-school.pc-7.q2","lessonId":"pc-7","kind":"mcq","prompt":"Your twenty-frame set is all shot at the same distance. What does the lesson suggest it needs?","choices":["Longer lenses","Variety of scale: establishing wides, mid-shots, details and portraits","A single colour","More saturation"],"answer":1,"hint":"Monotony.","explanation":"A working series needs variety of scale, otherwise it is monotonous however good each frame is.","level":2},
    {"id":"photo-art-school.pc-7.q3","lessonId":"pc-7","kind":"mcq","prompt":"Why edit ruthlessly in a series?","choices":["Fewer files save storage space and make the backups much faster to complete","Editors prefer short sets","Colours must match","A weak frame drags down the frames beside it, and twelve strong beat forty adequate"],"answer":3,"hint":"Neighbouring frames matter.","explanation":"The lesson says twelve strong frames beat forty adequate ones and a weak frame drags down its neighbours.","level":3},
    {"id":"photo-art-school.pl-1.q1","lessonId":"pl-1","kind":"mcq","prompt":"Which four properties can describe any lighting situation?","choices":["Quality, direction, intensity, colour","Aperture, shutter, ISO, focus","Hue, saturation, luminance, contrast, sharpness","Key, fill, rim, background"],"answer":0,"hint":"Think soft/hard, where from, how much, what temperature.","explanation":"The lesson lists quality, direction, intensity and colour as the four properties of light.","level":1},
    {"id":"photo-art-school.pl-1.q2","lessonId":"pl-1","kind":"mcq","prompt":"You have a bare flash and want softer light on a portrait. What works?","choices":["Lower ISO","Move the flash further away","Make the source bigger or bring it closer","Stop down the lens"],"answer":2,"hint":"Quality depends on source size relative to subject.","explanation":"Softness depends on source size relative to the subject, so enlarge the source or bring it closer.","level":2},
    {"id":"photo-art-school.pl-1.q3","lessonId":"pl-1","kind":"mcq","prompt":"Why is bottom light the horror-film convention?","choices":["It makes colour cooler","It hides the eyes","It is the hardest direction to produce with ordinary studio equipment","It inverts the lifelong assumption that light falls from above"],"answer":3,"hint":"Think about daily experience.","explanation":"Light normally comes from above, so lighting from below feels unnatural and unsettling.","level":3},
    {"id":"photo-art-school.pl-2.q1","lessonId":"pl-2","kind":"mcq","prompt":"What does blue hour balance, according to the lesson?","choices":["Sun against shadow","The fading sky against artificial lights","Warm skin against cool shade","Fog against rain"],"answer":1,"hint":"It comes after sunset.","explanation":"Blue hour balances the fading sky against artificial lights so both can be exposed correctly together.","level":1},
    {"id":"photo-art-school.pl-2.q2","lessonId":"pl-2","kind":"mcq","prompt":"You must photograph a person at noon in hard sun. What does the lesson suggest?","choices":["Put them in open shade and use the sunlit street as background","Face them directly into the sun and shoot at the widest aperture available","Use the widest aperture and nothing else","Wait until evening only"],"answer":0,"hint":"Use hard light for shape and shadow, not faces.","explanation":"The lesson suggests using hard midday light for shape and shadow, or placing the subject in open shade against a sunlit background.","level":2},
    {"id":"photo-art-school.pl-2.q3","lessonId":"pl-2","kind":"mcq","prompt":"What is the lesson main caution about golden hour?","choices":["It always needs a tripod because the available light is so dim and low","It is too short","It makes almost anything look pleasant, which is not the same as good","It cannot light skin well"],"answer":2,"hint":"Its risk is sentimentality.","explanation":"The lesson warns that golden light is easy and flattering, which risks sentimentality rather than quality.","level":3},
    {"id":"photo-art-school.pl-3.q1","lessonId":"pl-3","kind":"mcq","prompt":"Which window orientation does the lesson say produced most great Western portraiture before electric light?","choices":["South-facing","East-facing","North-facing","Skylight only"],"answer":2,"hint":"Consistent soft light.","explanation":"The lesson names the north-facing window as the source of most of the greatest portraiture.","level":1},
    {"id":"photo-art-school.pl-3.q2","lessonId":"pl-3","kind":"mcq","prompt":"The shadow side of a window-lit face is too dark. What quick fix does the lesson give?","choices":["Add a reflector on the shadow side","Move the subject to face the window","Raise shutter speed","Use a longer lens"],"answer":0,"hint":"Bounce light back.","explanation":"A white board, sheet or wall bounces light into the shadows; moving it closer reduces contrast.","level":2},
    {"id":"photo-art-school.pl-3.q3","lessonId":"pl-3","kind":"mcq","prompt":"Which pattern is defined by a small triangle of light on the shadow-side cheek?","choices":["Butterfly","Loop","Split","Rembrandt"],"answer":3,"hint":"Named for a Dutch painter.","explanation":"Rembrandt lighting produces a small triangle of light on the shadow-side cheek.","level":3},
    {"id":"photo-art-school.pl-4.q1","lessonId":"pl-4","kind":"mcq","prompt":"Why is direct on-camera flash disliked?","choices":["It is too bright","The source is tiny and on the lens axis, giving hard, frontal light","It is always the wrong colour, which clashes badly with the ambient light","It cannot sync with shutters"],"answer":1,"hint":"Source size and position.","explanation":"A tiny source on the lens axis gives flat faces, black shadows behind and red eye.","level":1},
    {"id":"photo-art-school.pl-4.q2","lessonId":"pl-4","kind":"mcq","prompt":"You want fill flash outdoors that nobody can tell is flash. What compensation does the lesson suggest?","choices":["0 stops, so the flash matches the ambient light exactly","-1 to -2 stops","Full power, so the flash overpowers the ambient light","+2 stops, so the flash is the dominant light"],"answer":1,"hint":"Just enough to lift the face.","explanation":"The lesson says dial flash to -1 to -2 stops of compensation so it lifts the face subtly.","level":2},
    {"id":"photo-art-school.pl-4.q3","lessonId":"pl-4","kind":"mcq","prompt":"Why does shutter speed control the ambient light but not the flash exposure?","choices":["Flash light does not reach the sensor until the shutter closes","Ambient light is always dimmer than the flash at any distance","Flash is fixed to 1/200s and cannot be changed by the camera","Flash duration is extremely short"],"answer":3,"hint":"Think of how brief the burst is.","explanation":"Because the flash burst is so short, shutter speed mainly affects ambient light while aperture and flash power control the flash.","level":3},
    {"id":"photo-art-school.pl-5.q1","lessonId":"pl-5","kind":"mcq","prompt":"What two jobs does every modifier do?","choices":["Make the source bigger and softer, or smaller and more controlled","Raise or lower power","Add or remove colour","Warm or cool the light"],"answer":0,"hint":"Think size.","explanation":"Modifiers either enlarge the source for softer light or shrink and control it for harder, directional light.","level":1},
    {"id":"photo-art-school.pl-5.q2","lessonId":"pl-5","kind":"mcq","prompt":"You want a pool of light on a face with the room going black. Which tool fits?","choices":["White ceiling bounce","Large umbrella","Grid or snoot","Shoot-through umbrella"],"answer":2,"hint":"Restrict the spread.","explanation":"Grids and snoots restrict spread so the light lands only where pointed.","level":2},
    {"id":"photo-art-school.pl-5.q3","lessonId":"pl-5","kind":"mcq","prompt":"A 4:1 or 8:1 key-to-fill ratio produces what look?","choices":["Overexposed highlights across the whole frame","Colour-shifted towards the warm end of the spectrum","Flat and commercial, with almost no shadow","Dramatic and cinematic"],"answer":3,"hint":"Compare with 1:1.","explanation":"The lesson says 1:1 is flat and commercial, while 4:1 or 8:1 is dramatic and cinematic.","level":3},
    {"id":"photo-art-school.pl-6.q1","lessonId":"pl-6","kind":"mcq","prompt":"What does chiaroscuro mean in Italian?","choices":["Dark colour","Light-dark","Soft shadow","Golden light"],"answer":1,"hint":"Two words joined.","explanation":"Chiaroscuro means light-dark: the modelling of form through strong contrast.","level":1},
    {"id":"photo-art-school.pl-6.q2","lessonId":"pl-6","kind":"mcq","prompt":"To recreate Caravaggio-style light with a camera, what setup does the lesson give?","choices":["A small hard source high and to one side, no fill, exposing for highlights","Overcast daylight","Ring flash","Large softbox in front with fill"],"answer":0,"hint":"Small, hard, one direction.","explanation":"Caravaggio used a small hard source high and to one side with no fill; expose for highlights and let shadows go black.","level":2},
    {"id":"photo-art-school.pl-6.q3","lessonId":"pl-6","kind":"mcq","prompt":"What transferable insight does the lesson draw about shadow?","choices":["Shadow is determined mainly by lens choice and the sensor format","Shadow is a flaw to eliminate","Shadow is information that masters lit to place","Shadow only matters in black and white"],"answer":2,"hint":"Beginners versus masters.","explanation":"Beginners light to eliminate shadow; the masters lit to place it.","level":3},
    {"id":"photo-art-school.pl-7.q1","lessonId":"pl-7","kind":"mcq","prompt":"How does the lesson describe city light at night?","choices":["Always colour-neutral","A single even glow that fills every street evenly with light","Pools of hard small sources with brutal fall-off","Entirely soft"],"answer":2,"hint":"Shop windows, streetlights.","explanation":"Cities at night are lit by pools, each a hard small source with brutal fall-off.","level":1},
    {"id":"photo-art-school.pl-7.q2","lessonId":"pl-7","kind":"mcq","prompt":"Autofocus hunts in the dark. What does the lesson suggest?","choices":["Focus on a light-dark edge or pre-focus manually and wait for the subject","Use the slowest shutter","Stop down to f/22","Turn on continuous AF"],"answer":0,"hint":"AF needs contrast.","explanation":"Focus on an edge where light meets dark, or pre-focus at a set distance and wait for the subject.","level":2},
    {"id":"photo-art-school.pl-7.q3","lessonId":"pl-7","kind":"tf","prompt":"The lesson treats black in a night photograph as a failure of exposure.","answer":1,"hint":"It can carry a picture.","explanation":"The lesson says black is the majority of the frame and can carry a picture entirely; it is not a failure.","level":3},
    {"id":"photo-art-school.pk-1.q1","lessonId":"pk-1","kind":"mcq","prompt":"Which three dimensions of colour does the lesson name?","choices":["Warmth, tint and contrast, as shown on the camera","Shade, tone and tint, as used in paint mixing","Red, green and blue, the primaries of light","Hue, saturation, luminance"],"answer":3,"hint":"Position, intensity, brightness.","explanation":"Colour has hue, saturation and luminance.","level":1},
    {"id":"photo-art-school.pk-1.q2","lessonId":"pk-1","kind":"mcq","prompt":"A frame has a red coat as the only warm object in a cold scene. According to the lesson, colour here is doing what?","choices":["Acting by default","Acting as structure that directs the eye","Creating noise","Lowering contrast"],"answer":1,"hint":"It is where you want the eye.","explanation":"The lesson uses this as an example of colour becoming structure rather than default.","level":2},
    {"id":"photo-art-school.pk-1.q3","lessonId":"pk-1","kind":"mcq","prompt":"What was the significance of William Eggleston 1976 MoMA exhibition?","choices":["It introduced digital photography to the art museum world for the first time","It marked colour becoming a subject rather than a description","It was the first black and white show","It banned dye-transfer"],"answer":1,"hint":"It was widely panned at the time.","explanation":"The lesson says it was reviewed badly but is now understood as when colour became a subject.","level":3},
    {"id":"photo-art-school.pk-2.q1","lessonId":"pk-2","kind":"mcq","prompt":"Which pair is complementary?","choices":["Yellow and green","Violet and blue","Red and orange","Blue and orange"],"answer":3,"hint":"Opposite on the wheel.","explanation":"Blue and orange sit opposite on the wheel and give maximum contrast.","level":1},
    {"id":"photo-art-school.pk-2.q2","lessonId":"pk-2","kind":"mcq","prompt":"You want to use blue-orange harmony in street work. What does the lesson recommend?","choices":["Scout for a blue wall and put an orange subject against it","Add a coloured filter to every shot to impose the harmony on it","Use only midday light","Invent it in post"],"answer":0,"hint":"Scouting tool, not editing tool.","explanation":"The lesson says use the colour wheel to scout, since harmony invented in post is usually visible and bad.","level":2},
    {"id":"photo-art-school.pk-2.q3","lessonId":"pk-2","kind":"mcq","prompt":"Why do analogous schemes need luminance contrast?","choices":["Skin tones disappear","They are too saturated","Neighbouring hues are harmonious but easily boring, so contrast must come from brightness","They cannot include red"],"answer":2,"hint":"Hue contrast is low.","explanation":"Analogous hues are unified and calm but flat, so luminance contrast keeps them interesting.","level":3},
    {"id":"photo-art-school.pk-3.q1","lessonId":"pk-3","kind":"mcq","prompt":"Which is bluer in colour temperature, 3000K or 8000K?","choices":["They are equal","Neither","3000K","8000K"],"answer":3,"hint":"Higher Kelvin means bluer.","explanation":"Higher Kelvin is bluer because it describes the emitting black body temperature; deep shade is around 8000K.","level":1},
    {"id":"photo-art-school.pk-3.q2","lessonId":"pk-3","kind":"mcq","prompt":"You set white balance to tungsten while shooting in daylight. What happens?","choices":["Only shadows change","Everything goes blue","Everything goes orange","Colours stay unchanged"],"answer":1,"hint":"White balance pushes in the opposite direction.","explanation":"Tungsten setting compensates for orange light, so in daylight everything shifts blue.","level":2},
    {"id":"photo-art-school.pk-3.q3","lessonId":"pk-3","kind":"mcq","prompt":"Why do some fluorescent interiors look sickly regardless of Kelvin?","choices":["They add a green spike needing magenta tint correction on a separate axis","Kelvin cannot be changed","They flicker","They are too dim"],"answer":0,"hint":"Not purely temperature.","explanation":"Fluorescent and cheap LED light add a green spike corrected on the tint axis, not by Kelvin.","level":3},
    {"id":"photo-art-school.pk-4.q1","lessonId":"pk-4","kind":"mcq","prompt":"What survives when converting to black and white?","choices":["Colour casts","Hue only","Luminance only","Saturation only"],"answer":2,"hint":"Brightness remains.","explanation":"In monochrome hue disappears and only luminance survives.","level":1},
    {"id":"photo-art-school.pk-4.q2","lessonId":"pk-4","kind":"mcq","prompt":"You want almost-black skies in a landscape conversion. Which filter effect does the lesson name?","choices":["Yellow","Blue","Red","Green"],"answer":2,"hint":"Think Ansel Adams.","explanation":"A red filter darkens blue sky dramatically, as in Adams skies.","level":2},
    {"id":"photo-art-school.pk-4.q3","lessonId":"pk-4","kind":"mcq","prompt":"Why does a red apple on green grass vanish in conversion?","choices":["Red and green can convert to nearly identical greys","Black and white removes shape and form from every part of a picture","Apples have no texture","It has too little saturation"],"answer":0,"hint":"Only luminance remains.","explanation":"The two hues can have similar luminance, so they turn into nearly identical greys.","level":3},
    {"id":"photo-art-school.pk-5.q1","lessonId":"pk-5","kind":"mcq","prompt":"What does white symbolise in much of East and South Asia, per the lesson?","choices":["Luck","Danger","Celebration","Mourning"],"answer":3,"hint":"Contrast with Western weddings.","explanation":"The lesson says white is mourning across much of East and South Asia.","level":1},
    {"id":"photo-art-school.pk-5.q2","lessonId":"pk-5","kind":"mcq","prompt":"You are photographing a culture not your own. What does the lesson advise?","choices":["Apply your own colour associations","Do not assume they transfer and ask","Grade everything to teal-and-orange","Desaturate all images"],"answer":1,"hint":"Documentary ethics.","explanation":"Do not assume your associations transfer, and do not grade someone else home into a look; ask.","level":2},
    {"id":"photo-art-school.pk-5.q3","lessonId":"pk-5","kind":"mcq","prompt":"Which cinematic convention does the lesson link to institutions and menace?","choices":["Bleached and desaturated","Sickly green","Teal-and-orange","Warm gold"],"answer":1,"hint":"Think hospital corridors.","explanation":"Sickly green is the convention for institutions and menace.","level":3},
    {"id":"photo-art-school.pk-6.q1","lessonId":"pk-6","kind":"mcq","prompt":"What does the lesson say a palette usually is?","choices":["A camera mode","A colour chart","A single filter","An accumulation of consistent decisions"],"answer":3,"hint":"It is rarely a filter.","explanation":"A palette is built from consistent decisions about light, location, skin treatment and black point.","level":1},
    {"id":"photo-art-school.pk-6.q2","lessonId":"pk-6","kind":"mcq","prompt":"You are starting a new project and want a consistent look. What does the lesson recommend?","choices":["Start from constraints: a few hues, a time of day, a contrast level","Edit each frame differently to match the unique mood of its scene","Use random colours","Pick a preset first"],"answer":0,"hint":"Constraints rather than presets.","explanation":"Choose two or three hues, a time of day and a contrast level, and apply them throughout.","level":2},
    {"id":"photo-art-school.pk-6.q3","lessonId":"pk-6","kind":"mcq","prompt":"Why should skin tone grading be checked across the full range of subjects?","choices":["Skin does not matter to viewers as long as the overall palette looks consistent","Only luminance matters","Presets calibrated on light skin can render deeper tones muddy or grey","All skin tones share one value"],"answer":2,"hint":"One number does not fit all.","explanation":"The lesson warns a grading approach calibrated only on light skin can muddy deeper skin tones.","level":3},
    {"id":"photo-art-school.pg-1.q1","lessonId":"pg-1","kind":"mcq","prompt":"Which eye should you focus on in a portrait?","choices":["The nose","Either, it does not matter","The far eye","The near eye"],"answer":3,"hint":"Always the same one.","explanation":"The lesson says focus on the near eye, always.","level":1},
    {"id":"photo-art-school.pg-1.q2","lessonId":"pg-1","kind":"mcq","prompt":"Your subject looks rigid when told to relax. What does the lesson recommend instead?","choices":["Say relax again, more firmly, until their shoulders finally drop","Give a task such as look out of the window or walk toward me","Stop shooting","Use a faster shutter"],"answer":1,"hint":"Tasks produce natural bodies.","explanation":"Directions that give a task produce natural bodies, whereas relax produces rigidity.","level":2},
    {"id":"photo-art-school.pg-1.q3","lessonId":"pg-1","kind":"mcq","prompt":"What is the difference between environmental and studio portraits?","choices":["Environmental portraits use context to explain the person; studio portraits strip context to focus on the face","Environmental always use long lenses","Studio portraits need no light","There is no difference"],"answer":0,"hint":"Different claims.","explanation":"Both are legitimate; they make different claims about the subject.","level":3},
    {"id":"photo-art-school.pg-2.q1","lessonId":"pg-2","kind":"mcq","prompt":"Which lens range does the lesson recommend for street photography?","choices":["200mm+","14-20mm","28-50mm","85-135mm"],"answer":2,"hint":"Wide to normal.","explanation":"Wide-to-normal lenses of 28-50mm, getting close, are recommended.","level":1},
    {"id":"photo-art-school.pg-2.q2","lessonId":"pg-2","kind":"mcq","prompt":"You see a promising scene. What does the lesson suggest?","choices":["Switch to a long lens","Shoot one frame","Work the scene with ten or twenty frames","Wait for autofocus"],"answer":2,"hint":"Work the scene.","explanation":"The lesson advises ten or twenty frames of a promising situation rather than one.","level":2},
    {"id":"photo-art-school.pg-2.q3","lessonId":"pg-2","kind":"mcq","prompt":"Which statement about law and ethics in street photography matches the lesson?","choices":["Photographing in public is often legal but ethics go beyond the law, such as not exploiting vulnerable people","Law is identical in every country","Ethics only apply to commercial work","If it is legal, it is ethical"],"answer":0,"hint":"Different things.","explanation":"The lesson says law and ethics are different, and vulnerability is not free subject matter.","level":3},
    {"id":"photo-art-school.pg-3.q1","lessonId":"pg-3","kind":"mcq","prompt":"What does the lesson say is the main reason most landscape photographs fail?","choices":["Low resolution","Too much colour","Wrong lens","No foreground"],"answer":3,"hint":"Think depth.","explanation":"Most landscape photographs fail because they lack a foreground.","level":1},
    {"id":"photo-art-school.pg-3.q2","lessonId":"pg-3","kind":"mcq","prompt":"Which filter does the lesson say cannot be replicated in software?","choices":["Graduated ND","Polarising filter","Warming filter","Soft-focus filter"],"answer":1,"hint":"It cuts reflections.","explanation":"A polariser cuts reflections off water and foliage and deepens sky in a way software cannot.","level":2},
    {"id":"photo-art-school.pg-3.q3","lessonId":"pg-3","kind":"mcq","prompt":"The lesson calls landscape the genre most prone to what?","choices":["Technical errors","Beautiful pictures with nothing to say","Overexposure","Cropping mistakes"],"answer":1,"hint":"Same locations, same drone.","explanation":"It warns the genre often yields beautiful pictures with nothing to say, and suggests asking about your relationship to place.","level":3},
    {"id":"photo-art-school.pg-4.q1","lessonId":"pg-4","kind":"mcq","prompt":"Which edit is allowed in a news context per the lesson?","choices":["Compositing two frames into one stronger image","Staging a scene for the camera when events are slow","Removing an object that distracts from the subject","Adjusting global tone and contrast"],"answer":3,"hint":"Global changes only.","explanation":"Global tone, contrast, colour balance and crop are allowed; adding or removing content is not.","level":1},
    {"id":"photo-art-school.pg-4.q2","lessonId":"pg-4","kind":"mcq","prompt":"Where does the lesson say most ethical failures in photojournalism happen?","choices":["Captions","Lens choice","Printing","Cropping"],"answer":0,"hint":"Words, not pixels.","explanation":"The lesson says most ethical failures are caption failures.","level":2},
    {"id":"photo-art-school.pg-4.q3","lessonId":"pg-4","kind":"mcq","prompt":"What lesson does the FSA archive teach?","choices":["It is a studio archive","Documentary is always neutral","It is both a great documentary corpus and a case study in government-funded persuasion","It was shot only in colour"],"answer":2,"hint":"Two facts held at once.","explanation":"Both facts are true: it is fine documentary and government-funded persuasion.","level":3},
    {"id":"photo-art-school.pg-5.q1","lessonId":"pg-5","kind":"mcq","prompt":"Why is still life described as merciless?","choices":["It is hard to focus","It needs expensive gear","Subjects move","Everything in the frame is your decision, so every weakness is authorship"],"answer":3,"hint":"Nothing is left to chance.","explanation":"Since nothing moves, every weakness is yours.","level":1},
    {"id":"photo-art-school.pg-5.q2","lessonId":"pg-5","kind":"mcq","prompt":"You photograph a glossy object. What does the lesson say you light?","choices":["The object only, using a small hard light source aimed at it","The reflection, such as with a large white card","The background only","The camera"],"answer":1,"hint":"Glossy objects reflect the room.","explanation":"On glossy surfaces you light what is reflected, so a large white card becomes the highlight.","level":2},
    {"id":"photo-art-school.pg-5.q3","lessonId":"pg-5","kind":"mcq","prompt":"Which lighting approach suits bottles, per the lesson?","choices":["Back-lighting through a diffuser","On-camera flash aimed straight at the bottle","Direct front light from a small bare lamp","Hard raking light skimming across the glass"],"answer":0,"hint":"Make glass glow.","explanation":"Back-lighting through a diffuser makes glass and liquid glow and separates them from the background.","level":3},
    {"id":"photo-art-school.pg-6.q1","lessonId":"pg-6","kind":"mcq","prompt":"What is keystoning?","choices":["Lens flare","Over-sharpening","Vertical lines converging when a wide lens points up","Colour fringing along high-contrast edges of the building"],"answer":2,"hint":"The building appears to fall backwards.","explanation":"Pointing a wide lens upward makes verticals converge, the defining architectural problem.","level":1},
    {"id":"photo-art-school.pg-6.q2","lessonId":"pg-6","kind":"mcq","prompt":"Which lens is the historical solution to keystoning?","choices":["Telephoto zoom","Fisheye","Tilt-shift","Macro"],"answer":2,"hint":"It shifts the image circle.","explanation":"A tilt-shift lens keeps the sensor parallel to the facade while shifting the image circle.","level":2},
    {"id":"photo-art-school.pg-6.q3","lessonId":"pg-6","kind":"mcq","prompt":"When would you include people in architectural photography?","choices":["When the subject is architecture-as-life","Only for scale in landscapes","Only at noon","Never"],"answer":0,"hint":"Binet versus Baan.","explanation":"People suit architecture-as-life; architecture-as-form excludes them.","level":3},
    {"id":"photo-art-school.pg-7.q1","lessonId":"pg-7","kind":"mcq","prompt":"What single constraint defines event photography, according to the lesson?","choices":["Heavy post-production","Tight budgets","Low light","It happens once and cannot be reshot"],"answer":3,"hint":"Reliability is everything.","explanation":"Event photography is defined by the fact that it happens once, so every other skill is subordinated to reliability.","level":1},
    {"id":"photo-art-school.pg-7.q2","lessonId":"pg-7","kind":"mcq","prompt":"Your camera has two card slots. What does the lesson advise?","choices":["Use one for video","Shoot to dual slots and back up twice before sleeping","Format cards between shots","Use the slower card for RAW files and the faster card for JPEG"],"answer":1,"hint":"Cards fail.","explanation":"The lesson says cards fail, so record to both slots and back up twice.","level":2},
    {"id":"photo-art-school.pg-7.q3","lessonId":"pg-7","kind":"mcq","prompt":"Why does the lesson say to photograph the audience during a speech?","choices":["To fill the card","Reactions are frequently better than the event itself","Speeches are boring, so the audience makes a better subject","It is required by contract"],"answer":1,"hint":"Think about what tells the story.","explanation":"The lesson says reactions are frequently better than the event, such as the mother during the vows.","level":3},
    {"id":"photo-art-school.pg-8.q1","lessonId":"pg-8","kind":"mcq","prompt":"What does the lesson call genres?","choices":["Marketing categories","Technical limits","Final destinations","Training wheels"],"answer":3,"hint":"Nobody serious has a body of work called by one.","explanation":"Genres are training wheels; serious bodies of work are specific enquiries that happen to be conducted in a genre.","level":1},
    {"id":"photo-art-school.pg-8.q2","lessonId":"pg-8","kind":"mcq","prompt":"You want to start a project. The lesson suggests writing what?","choices":["One paragraph stating what it is about","A pricing sheet","A shot count","A gear list"],"answer":0,"hint":"If you cannot, it is only a subject.","explanation":"If you cannot write the one-paragraph statement it is a subject, not yet a project.","level":2},
    {"id":"photo-art-school.pg-8.q3","lessonId":"pg-8","kind":"mcq","prompt":"Why does constraint generate originality more reliably than freedom?","choices":["Constraints speed up editing","It limits cost","A self-imposed restriction such as one lens, one place, one year makes work coherent","Constraints remove criticism"],"answer":2,"hint":"Think of famous photographers.","explanation":"The lesson says the photographers we know mostly worked under self-imposed restriction, which made the work coherent.","level":3},
    {"id":"photo-art-school.pe-1.q1","lessonId":"pe-1","kind":"mcq","prompt":"What did editing historically mean in photography?","choices":["Retouching skin and blemishes on portraits","Printing the final images for an exhibition","Adjusting tones and colours in each image","Choosing which frames to use"],"answer":3,"hint":"Selection versus processing.","explanation":"Editing meant selecting frames; processing meant adjusting them.","level":1},
    {"id":"photo-art-school.pe-1.q2","lessonId":"pe-1","kind":"mcq","prompt":"You have just returned from a shoot. When does the lesson suggest judging your best frames?","choices":["Immediately that night, while the shoot is still fresh","After leaving them for a week","Only after every frame has been fully processed","Never, since your own judgement is unreliable"],"answer":1,"hint":"Memory contaminates judgment.","explanation":"You cannot see your own work the day you shot it, so leave it for a week before the second pass.","level":2},
    {"id":"photo-art-school.pe-1.q3","lessonId":"pe-1","kind":"mcq","prompt":"Why should you select before processing?","choices":["Processing frames you will not use wastes a weekend and produces nothing","Software requires it","Selection removes noise","Processing is expensive"],"answer":0,"hint":"Order of operations.","explanation":"The lesson says processing a hundred unused frames is how photographers spend weekends and produce nothing.","level":3},
    {"id":"photo-art-school.pe-2.q1","lessonId":"pe-2","kind":"mcq","prompt":"What does the lesson list as the first step of a good global edit?","choices":["Sharpening the image at its final output size","White balance matched to the lighting of the scene","Setting black and white points","Local adjustments to the brightest areas of the frame"],"answer":2,"hint":"Set the ends.","explanation":"The first step is setting black and white points using the histogram.","level":1},
    {"id":"photo-art-school.pe-2.q2","lessonId":"pe-2","kind":"mcq","prompt":"You want a matte, faded film look. What do you do on the tone curve?","choices":["Add a strong S-curve","Drag the top-right point to zero","Lift the bottom-left point","Drop the bottom-left point"],"answer":2,"hint":"Blacks do not go fully black.","explanation":"Lifting the bottom-left point of the curve creates the matte faded look; dropping it deepens blacks.","level":2},
    {"id":"photo-art-school.pe-2.q3","lessonId":"pe-2","kind":"mcq","prompt":"What is described as the most common failure of modern editing?","choices":["Over-lifted shadows leaving no dark areas","Too little saturation","Over-cropping","Under-sharpening"],"answer":0,"hint":"Artificial and lifeless.","explanation":"A picture with no dark areas reads as artificial and lifeless.","level":3},
    {"id":"photo-art-school.pe-3.q1","lessonId":"pe-3","kind":"mcq","prompt":"What are dodging and burning?","choices":["Sharpening and softening","Warming and cooling","Cropping and rotating","Lightening and darkening selected areas"],"answer":3,"hint":"Darkroom techniques.","explanation":"Dodging lightens and burning darkens selected areas.","level":1},
    {"id":"photo-art-school.pe-3.q2","lessonId":"pe-3","kind":"mcq","prompt":"A bright corner distracts from your subject. What local fix does the lesson suggest?","choices":["Saturate it so it blends into the colours","Burn it down","Dodge it so that the corner is lightened further","Sharpen it to give the corner more crisp detail"],"answer":1,"hint":"Direct the eye away.","explanation":"Burn down bright corners and distracting patches so the eye goes to the subject.","level":2},
    {"id":"photo-art-school.pe-3.q3","lessonId":"pe-3","kind":"mcq","prompt":"What did Ansel Adams mean by the negative being the score and the print the performance?","choices":["Negatives are worthless","Printing choices such as dodging and burning interpret the raw material","Prints should be untouched","Scores are for music only"],"answer":1,"hint":"Interpretation.","explanation":"The negative holds the potential and the print is an interpretation made through dodging and burning.","level":3},
    {"id":"photo-art-school.pe-4.q1","lessonId":"pe-4","kind":"mcq","prompt":"On which three axes does professional colour grading work, per band?","choices":["Red, green, blue","Temperature, tint, vibrance","Shadows, midtones, highlights","Hue, saturation, luminance"],"answer":3,"hint":"Colour dimensions again.","explanation":"Grading works on hue, saturation and luminance for each colour band.","level":1},
    {"id":"photo-art-school.pe-4.q2","lessonId":"pe-4","kind":"mcq","prompt":"You want to deepen a sky without touching other colours. Which move does the lesson suggest?","choices":["Darken the luminance of blues","Raise global contrast across the whole image","Boost orange saturation to make the blue stand out","Lift shadows so that more detail shows in the sky"],"answer":0,"hint":"Per-hue luminance.","explanation":"Darkening blues deepens sky without affecting other regions.","level":2},
    {"id":"photo-art-school.pe-4.q3","lessonId":"pe-4","kind":"mcq","prompt":"Why is cool shadows with warm highlights the near-universal cinematic default?","choices":["It matches the colour of tungsten lamps inside the interiors of films","It hides noise","It exaggerates the natural blue-shadow/warm-sun relationship","It is required by cameras"],"answer":2,"hint":"Nature already does it.","explanation":"It amplifies the natural relationship between blue shadows and warm sunlight.","level":3},
    {"id":"photo-art-school.pe-5.q1","lessonId":"pe-5","kind":"mcq","prompt":"What does sharpening actually do?","choices":["Removes noise from flat areas of the image","Raises the resolution of the file you export","Adds detail that the lens never recorded","Increases local contrast at edges"],"answer":3,"hint":"It does not add detail.","explanation":"Sharpening increases local contrast at edges so detail reads more clearly.","level":1},
    {"id":"photo-art-school.pe-5.q2","lessonId":"pe-5","kind":"mcq","prompt":"You export for web. Which colour space does the lesson recommend?","choices":["Adobe RGB","sRGB","CMYK","ProPhoto"],"answer":1,"hint":"Browsers may ignore profiles.","explanation":"sRGB is recommended for web because other spaces can look desaturated in browsers that ignore profiles.","level":2},
    {"id":"photo-art-school.pe-5.q3","lessonId":"pe-5","kind":"mcq","prompt":"What is the recommended processing order for noise and sharpening?","choices":["Denoise first, sharpen last at output size","Both at the same time","Neither is ordered","Sharpen first, denoise last"],"answer":0,"hint":"Last mile.","explanation":"Denoise first and sharpen last, for the size the picture will be seen.","level":3},
    {"id":"photo-art-school.pe-6.q1","lessonId":"pe-6","kind":"mcq","prompt":"What does non-destructive editing mean?","choices":["Edits are irreversible","Only JPEGs are used","Originals are never altered; adjustments are stored as instructions","Original files are deleted after editing so that only the exports remain"],"answer":2,"hint":"Original untouched.","explanation":"The original file is never changed and adjustments are applied on export.","level":1},
    {"id":"photo-art-school.pe-6.q2","lessonId":"pe-6","kind":"mcq","prompt":"What is the 3-2-1 backup rule?","choices":["Three catalogues, two folders, one disk","Three days, two weeks, one month","Three copies, two media, one off-site","Three drives, two clouds, one NAS"],"answer":2,"hint":"Copies, media, location.","explanation":"Three copies on two different media with one off-site.","level":2},
    {"id":"photo-art-school.pe-6.q3","lessonId":"pe-6","kind":"mcq","prompt":"Why is cloud sync not a backup?","choices":["It faithfully replicates your deletions","It cannot store RAW","It is always offline","It is too slow"],"answer":0,"hint":"Think of a mistaken delete.","explanation":"Sync mirrors changes, so deleting a file deletes it everywhere.","level":3},
    {"id":"photo-art-school.pe-7.q1","lessonId":"pe-7","kind":"mcq","prompt":"What does the lesson say the real question about photographic manipulation is?","choices":["Which software was used and how many layers were involved in the edit","How large the file is","Whether it is constructed","Whether the alteration is consistent with what the image claims"],"answer":3,"hint":"Claim versus alteration.","explanation":"All photographs are constructed; the test is whether the alteration fits what the image claims.","level":1},
    {"id":"photo-art-school.pe-7.q2","lessonId":"pe-7","kind":"mcq","prompt":"Generative fill is used in a commercial composite. How does the lesson regard it?","choices":["Fraud, since it adds invented content","Ordinary craft","Illegal in every commercial setting","Impossible, as the tools cannot make composites"],"answer":1,"hint":"Context sets the standard.","explanation":"In a commercial composite it is ordinary craft; presented as documentation it would be fabrication.","level":2},
    {"id":"photo-art-school.pe-7.q3","lessonId":"pe-7","kind":"mcq","prompt":"Why does disclosure matter more now?","choices":["It is legally required everywhere","Fabrication has become trivially easy","Cameras now record edits","Clients demand it"],"answer":1,"hint":"Think of ease.","explanation":"Generative tools make fabrication easy, so disclosure matters more than before.","level":3},
    {"id":"photo-art-school.pb-1.q1","lessonId":"pb-1","kind":"mcq","prompt":"In most jurisdictions, who owns copyright in a photograph at creation?","choices":["The camera maker","The subject","The client who paid","The photographer"],"answer":3,"hint":"Automatic.","explanation":"Copyright arises automatically and belongs to the photographer.","level":1},
    {"id":"photo-art-school.pb-1.q2","lessonId":"pb-1","kind":"mcq","prompt":"A client asks for all rights. What does the lesson say about price?","choices":["It should carry a much higher price","It should cost the same as an ordinary licence for use","It should be free, as a goodwill gesture to the client","It cannot be sold, since copyright cannot be transferred"],"answer":0,"hint":"Selling versus renting.","explanation":"A buyout sells the asset rather than renting it, so it should be priced much higher.","level":2},
    {"id":"photo-art-school.pb-1.q3","lessonId":"pb-1","kind":"mcq","prompt":"When is a model release generally required?","choices":["Never; releases are only a courtesy to subjects","For news photographs of people in public places","For commercial and advertising use","For fine art prints sold through a gallery only"],"answer":2,"hint":"Likeness in commerce.","explanation":"Releases are generally required for commercial and advertising use, not editorial, news or fine art.","level":3},
    {"id":"photo-art-school.pb-2.q1","lessonId":"pb-2","kind":"mcq","prompt":"Roughly how many days a year does a full-time photographer bill, according to the lesson?","choices":["30 to 50 billable days a year","300 billable days a year, as in a salaried job","200-250 billable days a year","80 to 120"],"answer":3,"hint":"Most time is not shooting.","explanation":"The lesson says perhaps 80 to 120 billable days a year.","level":1},
    {"id":"photo-art-school.pb-2.q2","lessonId":"pb-2","kind":"mcq","prompt":"What two components make up a commercial fee?","choices":["Equipment hire and travel costs","Creative fee and licence fee","Day rate and a performance bonus","Tax and a gratuity paid to the client"],"answer":1,"hint":"Time versus usage.","explanation":"Creative fee covers time and expertise; licence fee covers the value of usage.","level":2},
    {"id":"photo-art-school.pb-2.q3","lessonId":"pb-2","kind":"mcq","prompt":"Why price the job and not just the day?","choices":["The same labour can deliver very different value depending on usage","Clients dislike day rates because they cannot predict the final cost of a job","Tax rules","Days vary in length"],"answer":0,"hint":"National campaign versus local shop.","explanation":"Identical labour can produce an order of magnitude different value, so usage shapes price.","level":3},
    {"id":"photo-art-school.pb-3.q1","lessonId":"pb-3","kind":"mcq","prompt":"Which delivery rule does the lesson state about RAW files?","choices":["Deliver them as JPEG","Always include them","They are not delivered; a separate expensive licence if insisted","Deliver them free of charge whenever the client asks for them directly"],"answer":2,"hint":"They are negatives.","explanation":"RAW files are your negatives; handing them over requires a separate, expensive licence.","level":1},
    {"id":"photo-art-school.pb-3.q2","lessonId":"pb-3","kind":"mcq","prompt":"A client says they cannot pay but it is great exposure. What does the lesson suggest?","choices":["Ignore them","Accept immediately","Have a polite prepared answer offering a reduced-scope paid option","Argue publicly on social media about how clients undervalue photographers"],"answer":2,"hint":"Prepare in advance.","explanation":"Prepare a standard polite response that suggests a reduced-scope paid option.","level":2},
    {"id":"photo-art-school.pb-3.q3","lessonId":"pb-3","kind":"mcq","prompt":"When should you chase a late invoice?","choices":["Day one of lateness","After a full year, once the work is forgotten","Never, because chasing damages the client relationship","Day thirty, once the payment terms have expired"],"answer":0,"hint":"Early.","explanation":"Chase on day one of lateness rather than day thirty.","level":3},
    {"id":"photo-art-school.pb-4.q1","lessonId":"pb-4","kind":"mcq","prompt":"What is the iron rule of portfolios in the lesson?","choices":["Show only recent work, since clients care most about your latest style","Show 100 images","Show everything","Clients hire you to do again what they have seen you do"],"answer":3,"hint":"Be specific.","explanation":"Clients hire you to repeat what they have already seen you do.","level":1},
    {"id":"photo-art-school.pb-4.q2","lessonId":"pb-4","kind":"mcq","prompt":"How many images does the lesson suggest in a portfolio?","choices":["Five to eight, as a short sample","Fifteen to twenty-five","Fifty, so clients see your range","A hundred, to show the full breadth of your work"],"answer":1,"hint":"All excellent.","explanation":"Fifteen to twenty-five images, all excellent.","level":2},
    {"id":"photo-art-school.pb-4.q3","lessonId":"pb-4","kind":"mcq","prompt":"Why are self-directed projects the primary marketing tool in commercial photography?","choices":["They are cheaper for clients and photographers alike to produce","You cannot be hired for a job you have not demonstrated","Clients like free work","They are required for awards"],"answer":1,"hint":"Show the work you want.","explanation":"Nobody can hire you for a job you have never demonstrated, so personal work should mirror desired commissions.","level":3},
    {"id":"photo-art-school.pb-5.q1","lessonId":"pb-5","kind":"mcq","prompt":"Which work pays the highest rate per day but is least predictable?","choices":["Teaching and running workshops","Prints sold through galleries","Stock sold through agencies","Commissioned work"],"answer":3,"hint":"Highest and least predictable.","explanation":"Commissioned work is the highest rate per day and least predictable.","level":1},
    {"id":"photo-art-school.pb-5.q2","lessonId":"pb-5","kind":"mcq","prompt":"What share do galleries typically take on print sales, per the lesson?","choices":["40-50%","80% of the sale price","100% of the sale price","5-10% of the sale price"],"answer":0,"hint":"Roughly half.","explanation":"Galleries take 40-50% in return for access and legitimacy.","level":2},
    {"id":"photo-art-school.pb-5.q3","lessonId":"pb-5","kind":"mcq","prompt":"Why are teaching and workshops described as counter-cyclical?","choices":["They are seasonal","They pay more in booms","They hold up when commissions dry up","They need no skills"],"answer":2,"hint":"Income balance.","explanation":"They convert expertise to income and hold up when commissions dry up.","level":3},
    {"id":"photo-art-school.pb-6.q1","lessonId":"pb-6","kind":"mcq","prompt":"What does the lesson say gets you the second job?","choices":["Lower price","Luck","Better gear","Behaviour"],"answer":3,"hint":"Not ability.","explanation":"Ability gets the first job; behaviour gets the second.","level":1},
    {"id":"photo-art-school.pb-6.q2","lessonId":"pb-6","kind":"mcq","prompt":"During a shoot, what role does the lesson give the photographer?","choices":["The loudest voice, directing everyone","The calmest person present","The silent observer who never intervenes","The boss only, with no role in mood"],"answer":1,"hint":"People take cues.","explanation":"Clients and subjects take emotional cues from the photographer, so be the calmest person.","level":2},
    {"id":"photo-art-school.pb-6.q3","lessonId":"pb-6","kind":"mcq","prompt":"Why pay assistants promptly and properly?","choices":["The assistant today may be the photographer recommending you in five years","They work faster","It reduces tax","It is a law"],"answer":0,"hint":"Long game.","explanation":"The assistant on your set this year could be recommending you later.","level":3},
    {"id":"photo-art-school.ae-1.q1","lessonId":"ae-1","kind":"mcq","prompt":"How does the lesson define line?","choices":["A grid of evenly spaced guide marks","A boundary where one colour meets another","A moving point, the record of a gesture","A fixed edge between two flat areas"],"answer":2,"hint":"First mark humans made.","explanation":"Line is a moving point, preserving the speed, pressure and confidence of the hand.","level":1},
    {"id":"photo-art-school.ae-1.q2","lessonId":"ae-1","kind":"mcq","prompt":"Which line type builds tone from accumulated marks?","choices":["Contour lines that follow the edge","Gesture lines drawn with fast movement","Hatching and cross-hatching","Implied line formed by a row of gaps"],"answer":2,"hint":"Marks accumulate.","explanation":"Hatching and cross-hatching build tone from accumulated lines.","level":2},
    {"id":"photo-art-school.ae-1.q3","lessonId":"ae-1","kind":"mcq","prompt":"Why is a varied line thick in some places and thin in others?","choices":["It describes three-dimensional form with a single stroke","It looks random but is only a sign of a hurried hand in the drawing","Thick means finished","Pen ran out of ink"],"answer":0,"hint":"Form turning towards you.","explanation":"Thick where a form turns or catches shadow, thin where it recedes, creating three-dimensional form.","level":3},
    {"id":"photo-art-school.ae-2.q1","lessonId":"ae-2","kind":"mcq","prompt":"What distinguishes shape from form?","choices":["Shape is always filled with colour, while form is always left uncoloured","They are synonyms","Form is geometric only","Shape is two-dimensional, form three-dimensional or its illusion"],"answer":3,"hint":"Dimensions.","explanation":"Shape is a two-dimensional enclosed area; form is three-dimensional or its illusion.","level":1},
    {"id":"photo-art-school.ae-2.q2","lessonId":"ae-2","kind":"mcq","prompt":"Why do trained artists draw negative shapes?","choices":["They are easier to colour","The eye is less prejudiced about an abstract gap than about a known object","They hide errors","Negative shapes are bigger"],"answer":1,"hint":"Hand versus gap.","explanation":"The eye holds fewer assumptions about an abstract gap than about a hand.","level":2},
    {"id":"photo-art-school.ae-2.q3","lessonId":"ae-2","kind":"mcq","prompt":"Which depth device does the lesson call the oldest and most reliable?","choices":["Atmospheric perspective","Overlapping","Linear perspective","Relative size"],"answer":1,"hint":"Objects in front of others.","explanation":"Overlapping is the oldest and most reliable depth device.","level":3},
    {"id":"photo-art-school.ae-3.q1","lessonId":"ae-3","kind":"mcq","prompt":"What is value in art?","choices":["The purity or intensity of a given hue","The thickness of paint on the canvas","The market cost of a work at public auction","Relative lightness or darkness"],"answer":3,"hint":"Light and dark.","explanation":"Value is relative lightness or darkness and creates the illusion of form.","level":1},
    {"id":"photo-art-school.ae-3.q2","lessonId":"ae-3","kind":"mcq","prompt":"You want to test whether a design works at its most basic level. Which Japanese concept reduces it to two values?","choices":["Notan","Ukiyo-e","Sumi","Wabi-sabi"],"answer":0,"hint":"Black and white skeleton.","explanation":"Notan reduces an image to two values to test the underlying design.","level":2},
    {"id":"photo-art-school.ae-3.q3","lessonId":"ae-3","kind":"mcq","prompt":"Why does a painting with correct values and wrong colour still read, while the reverse turns to mud?","choices":["Mud is a pigment that can only be avoided by using limited colours","Colour is irrelevant","Value carries form and legibility and outranks colour","Values are harder to see"],"answer":2,"hint":"Squint test.","explanation":"Value does the work of form and legibility, so colour errors survive but value collapse does not.","level":3},
    {"id":"photo-art-school.ae-4.q1","lessonId":"ae-4","kind":"mcq","prompt":"What is actual texture?","choices":["The subject matter","The colour palette","The illusion of satin in a painting created with careful brushwork","The physical surface of the work itself, such as impasto ridges"],"answer":3,"hint":"Physical versus depicted.","explanation":"Actual texture is the physical surface: impasto, canvas weave, grain, tooth of paper.","level":1},
    {"id":"photo-art-school.ae-4.q2","lessonId":"ae-4","kind":"mcq","prompt":"Why does the lesson argue for standing before the real Van Gogh at least once?","choices":["It is cheaper","Reproductions flatten the physical texture of the paint","Colours are brighter on screen than they appear in the gallery","Frames matter"],"answer":1,"hint":"Where reproductions fail.","explanation":"Photographs flatten the ropes of paint and thick passages that you can only see in person.","level":2},
    {"id":"photo-art-school.ae-4.q3","lessonId":"ae-4","kind":"mcq","prompt":"What did Picasso and Braque do in 1912 that changed the picture surface, per the lesson?","choices":["Glued oilcloth to a canvas","Painted on sheets of glass instead of canvas","Used oil paint only and abandoned all other media","Used gold leaf to cover the entire canvas"],"answer":0,"hint":"The surface became an object.","explanation":"Gluing oilcloth to a canvas made the surface an object rather than a window.","level":3},
    {"id":"photo-art-school.ae-5.q1","lessonId":"ae-5","kind":"mcq","prompt":"Which elements outweigh almost anything else in visual weight?","choices":["A thin line running across the paper","A small shadow in the lower corner","A face or a figure","A pale background behind the subject"],"answer":2,"hint":"Human attention.","explanation":"The lesson says a face or figure outweighs almost anything because human attention is not neutral.","level":1},
    {"id":"photo-art-school.ae-5.q2","lessonId":"ae-5","kind":"mcq","prompt":"A designer wants a formal, stable, institutional feel. Which balance suits?","choices":["Progressive","Asymmetrical","Symmetrical","Random"],"answer":2,"hint":"Altarpieces and government buildings.","explanation":"Symmetrical balance reads formal, stable, sacred and institutional.","level":2},
    {"id":"photo-art-school.ae-5.q3","lessonId":"ae-5","kind":"mcq","prompt":"Why is a composition with three competing focal points described as having none?","choices":["Competing emphases cancel each other, leaving no hierarchy","Three is considered unlucky in many artistic traditions around the world","Colours clash","Viewers prefer three"],"answer":0,"hint":"Primary, secondary, supporting.","explanation":"Without a clear hierarchy of primary, secondary and supporting interest, nothing leads.","level":3},
    {"id":"photo-art-school.ae-6.q1","lessonId":"ae-6","kind":"mcq","prompt":"What does repetition with variation create?","choices":["Symmetry","Texture","Pattern only","Rhythm"],"answer":3,"hint":"Pattern becomes something else.","explanation":"Pattern with variation creates rhythm, which gives a sensation of movement.","level":1},
    {"id":"photo-art-school.ae-6.q2","lessonId":"ae-6","kind":"mcq","prompt":"Which rhythm changes an element gradually to create directional movement?","choices":["Alternating","Progressive","Random","Regular"],"answer":1,"hint":"Think spiral shell.","explanation":"Progressive rhythm changes gradually and gives directional movement, like a receding arcade.","level":2},
    {"id":"photo-art-school.ae-6.q3","lessonId":"ae-6","kind":"mcq","prompt":"How do Baroque and Renaissance compositions differ in handling the eye?","choices":["Baroque uses only symmetry","Baroque uses sweeping diagonals to make the eye travel; Renaissance uses stable triangles to stop it","They are the same","Renaissance uses diagonals"],"answer":1,"hint":"Movement versus stability.","explanation":"Baroque diagonals send the eye travelling, whereas Renaissance triangles stabilise it.","level":3},
    {"id":"photo-art-school.ae-7.q1","lessonId":"ae-7","kind":"mcq","prompt":"What does scale describe, according to the lesson?","choices":["The ratio of the parts of a figure to the whole figure","Colour intensity","Line thickness","Size relative to a norm, usually the human body"],"answer":3,"hint":"Distinguish from proportion.","explanation":"Scale is size relative to a norm, typically the human body; proportion is part-to-whole.","level":1},
    {"id":"photo-art-school.ae-7.q2","lessonId":"ae-7","kind":"mcq","prompt":"In an Egyptian relief the pharaoh is far larger than servants. What is this called?","choices":["Hierarchical proportion","Contrapposto, a weight-shifted pose","Sfumato, a soft blending of tones","Foreshortening, a shortened view"],"answer":0,"hint":"Size by importance.","explanation":"Hierarchical proportion sizes figures by importance rather than optical realism.","level":2},
    {"id":"photo-art-school.ae-7.q3","lessonId":"ae-7","kind":"mcq","prompt":"How does the lesson interpret El Greco elongated figures?","choices":["Copying Egyptian canons","Mistakes in drawing caused by an astigmatism in the painter eyes","Deliberate distortion straining upward toward the divine","Optical illusions"],"answer":2,"hint":"Accuracy applied to feeling.","explanation":"Distortion is expressive; El Greco figures strain toward the divine.","level":3},
    {"id":"photo-art-school.ae-8.q1","lessonId":"ae-8","kind":"mcq","prompt":"What two qualities must be held in tension, according to the lesson?","choices":["Line and form, as the two basic elements","Colour and value, as the two key contrasts","Scale and rhythm, as the two measures of size","Unity and variety"],"answer":3,"hint":"One thing versus interest.","explanation":"Unity (a work as one thing) and variety (interest) are balanced.","level":1},
    {"id":"photo-art-school.ae-8.q2","lessonId":"ae-8","kind":"mcq","prompt":"Which Gestalt principle lets viewers complete a shape you only implied?","choices":["Continuation","Closure","Proximity","Alignment"],"answer":1,"hint":"Completing the shape.","explanation":"Closure lets perception complete implied shapes.","level":2},
    {"id":"photo-art-school.ae-8.q3","lessonId":"ae-8","kind":"mcq","prompt":"Why is overworking called the most common way to destroy an artwork?","choices":["The freshness of a decisive mark cannot be recovered once softened repeatedly","Artists lose interest","Colours fade","The paint dries"],"answer":0,"hint":"Freshness.","explanation":"A decisive mark softened four times loses its freshness irrecoverably.","level":3},
    {"id":"photo-art-school.ad-1.q1","lessonId":"ad-1","kind":"mcq","prompt":"What does the lesson say is the real obstacle to drawing?","choices":["Lack of natural talent for judging proportion and shape","A weak hand","The symbol the brain substitutes for the object","Poor materials"],"answer":2,"hint":"Perception, not motor skill.","explanation":"The brain supplies stored symbols instead of reporting the shape actually seen.","level":1},
    {"id":"photo-art-school.ad-1.q2","lessonId":"ad-1","kind":"mcq","prompt":"Which exercise defeats naming by drawing without looking at the paper?","choices":["Stippling dots to build up tone","Thumbnails drawn at a very small size","Blind contour drawing","Gesture drawing in a timed short pose"],"answer":2,"hint":"Follow an edge with the eye only.","explanation":"Blind contour drawing follows an edge by eye while drawing without looking at the paper.","level":2},
    {"id":"photo-art-school.ad-1.q3","lessonId":"ad-1","kind":"mcq","prompt":"Why does the lesson favour fifty quick bad drawings over one laboured good one?","choices":["The corrections accumulate across volume","Quick drawings are always better than careful ones","Teachers prefer them because they are easier to mark","It saves paper and materials over a term"],"answer":0,"hint":"Volume beats quality early.","explanation":"Corrections accumulate with volume, so many quick drawings teach more.","level":3},
    {"id":"photo-art-school.ad-2.q1","lessonId":"ad-2","kind":"mcq","prompt":"How long does gesture drawing typically take, per the lesson?","choices":["Ten to twenty minutes for each pose","One hour for each full pose","Several days for each finished study","Thirty seconds to two minutes"],"answer":3,"hint":"Fast.","explanation":"Gesture drawings capture action in thirty seconds to two minutes.","level":1},
    {"id":"photo-art-school.ad-2.q2","lessonId":"ad-2","kind":"mcq","prompt":"In which order does the lesson combine the stages?","choices":["Detail first, then construction, and gesture last of all","Gesture, construction, then contour and detail","Construction, detail, gesture","Contour, gesture, construction"],"answer":1,"hint":"Energy first.","explanation":"Gesture first, construction second, contour and detail last.","level":2},
    {"id":"photo-art-school.ad-2.q3","lessonId":"ad-2","kind":"mcq","prompt":"What does the lesson say a hairy multi-line sketching habit reveals?","choices":["Skill and a confident, practised hand","Hesitation made visible","Good lighting in the studio","A fast and practised working speed"],"answer":1,"hint":"Same line eight times.","explanation":"Repeated lines are hesitation made visible, a habit rather than a limitation.","level":3},
    {"id":"photo-art-school.ad-3.q1","lessonId":"ad-3","kind":"mcq","prompt":"What is the core shadow, or terminator?","choices":["The edge of the cast shadow on the surface where the object sits","The reflected light","The brightest highlight","The darkest band where the form turns fully away from the light"],"answer":3,"hint":"Darker than the cast shadow interior.","explanation":"The core shadow is the darkest band where form turns away, darker than the cast shadow interior.","level":1},
    {"id":"photo-art-school.ad-3.q2","lessonId":"ad-3","kind":"mcq","prompt":"You make reflected light very bright and the form looks flat. What rule did you break?","choices":["Reflected light must stay darker than the lightest halftone","Reflected light should be pure white to show the glow of the surface","Highlights must vanish","Outlines must be thick"],"answer":0,"hint":"It flattens the form.","explanation":"Reflected light that is too bright breaks the illusion; it must stay darker than the lightest halftone.","level":2},
    {"id":"photo-art-school.ad-3.q3","lessonId":"ad-3","kind":"mcq","prompt":"Why is outlining then filling an error in shading?","choices":["It prevents hatching and so leaves the tones too smooth and even","It is slow","Real form has no outline, only edges where value changes","It wastes pencil"],"answer":2,"hint":"Edges are value changes.","explanation":"Form has no outline; edges are places where value changes.","level":3},
    {"id":"photo-art-school.ad-4.q1","lessonId":"ad-4","kind":"mcq","prompt":"Who formalised linear perspective around 1415, per the lesson?","choices":["Leonardo da Vinci, in his notebooks","Giotto, in the frescoes at Padua","Alberti, in a treatise written in 1415","Brunelleschi"],"answer":3,"hint":"Florentine architect.","explanation":"Brunelleschi formalised it around 1415; Alberti codified it in 1435.","level":1},
    {"id":"photo-art-school.ad-4.q2","lessonId":"ad-4","kind":"mcq","prompt":"You draw a corridor with one face parallel to the picture plane. How many vanishing points do you need?","choices":["Zero","One","Two","Three"],"answer":1,"hint":"Head-on view.","explanation":"One-point perspective applies when one face is parallel to the picture plane.","level":2},
    {"id":"photo-art-school.ad-4.q3","lessonId":"ad-4","kind":"mcq","prompt":"What caveat does the lesson give about linear perspective?","choices":["It is a Renaissance European convention describing a one-eyed, motionless viewer","It is only for architecture","It was invented in Egypt","It is always wrong"],"answer":0,"hint":"A tool, not reality.","explanation":"Other traditions, like Chinese handscrolls and Cubism, reject it deliberately.","level":3},
    {"id":"photo-art-school.ad-5.q1","lessonId":"ad-5","kind":"mcq","prompt":"Where is the halfway point of the classical figure, according to the lesson?","choices":["At the navel, near the centre of the body","At the waist, where the torso narrows","At the pubic bone","At the knees, where the leg bends"],"answer":2,"hint":"Not where beginners put it.","explanation":"The classical canon places the halfway point at the pubic bone, not the waist.","level":1},
    {"id":"photo-art-school.ad-5.q2","lessonId":"ad-5","kind":"mcq","prompt":"Which two masses does the lesson say produce most gesture?","choices":["Shoulders and knees","Head and hands","Ribcage and pelvis","Arms and legs"],"answer":2,"hint":"Connected by the spine.","explanation":"Gesture comes from the tilt, twist and separation of the ribcage and pelvis.","level":2},
    {"id":"photo-art-school.ad-5.q3","lessonId":"ad-5","kind":"mcq","prompt":"Why are bony landmarks reliable?","choices":["They do not change with pose or build","They are larger","They are symmetrical","They are brighter"],"answer":0,"hint":"Near the skin.","explanation":"Landmarks like clavicle and patella stay constant despite pose and build.","level":3},
    {"id":"photo-art-school.ad-6.q1","lessonId":"ad-6","kind":"mcq","prompt":"What are thumbnails, per the lesson?","choices":["Photographs taken to plan the arrangement of a scene","Erasers","Final drawings","Postage-stamp sketches testing arrangements"],"answer":3,"hint":"Six to ten, under a minute.","explanation":"Thumbnails are quick small sketches that test compositions before committing.","level":1},
    {"id":"photo-art-school.ad-6.q2","lessonId":"ad-6","kind":"mcq","prompt":"Which format does the lesson call static and formal?","choices":["Landscape","Square","Panorama","Portrait"],"answer":1,"hint":"Equal sides.","explanation":"Square is static and formal; portrait emphasises height; landscape breadth.","level":2},
    {"id":"photo-art-school.ad-6.q3","lessonId":"ad-6","kind":"mcq","prompt":"Why do beginners drift drawings toward the page middle, and what does the lesson say about it?","choices":["It hides errors","It reads as timid; let the subject touch or cross edges when the design calls for it","It is the best practice","It saves paper"],"answer":1,"hint":"Even margin of nothing.","explanation":"Even margins read as timid; subjects can touch or cross the edges.","level":3},
    {"id":"photo-art-school.ad-7.q1","lessonId":"ad-7","kind":"mcq","prompt":"Which medium does the lesson recommend for learning big value masses because it is too crude to fiddle with?","choices":["Ink","Pastel","Graphite","Charcoal"],"answer":3,"hint":"Rich, messy black.","explanation":"Charcoal is best for big masses because its crudeness discourages fiddling.","level":1},
    {"id":"photo-art-school.ad-7.q2","lessonId":"ad-7","kind":"mcq","prompt":"What advantage does toned paper offer?","choices":["You can work up into white and down into black from a middle value","It resists charcoal and graphite, so the marks stay crisp for much longer","It is waterproof","Cheaper"],"answer":0,"hint":"Mid-grey or tan.","explanation":"Toned paper lets you establish a middle and work both ways, teaching value relationships.","level":2},
    {"id":"photo-art-school.ad-7.q3","lessonId":"ad-7","kind":"mcq","prompt":"Why is digital drawing both a strength and a danger?","choices":["It lacks the full range of colours and tools that traditional artists use","It is expensive","Infinite reversibility makes it easy to avoid committing","It cannot make lines"],"answer":2,"hint":"Think undo.","explanation":"Undo is helpful but allows endless avoidance of commitment.","level":3},
    {"id":"photo-art-school.ac-1.q1","lessonId":"ac-1","kind":"mcq","prompt":"What are the additive primaries?","choices":["Cyan, magenta, yellow","Black, white, grey","Red, yellow, blue","Red, green, blue"],"answer":3,"hint":"Screens and sensors.","explanation":"Additive colour, i.e. light, uses red, green and blue.","level":1},
    {"id":"photo-art-school.ac-1.q2","lessonId":"ac-1","kind":"mcq","prompt":"You mix blue and yellow paint and get dull green, but cyan and yellow give vivid green. What explains this?","choices":["Cyan is lighter","The RYB wheel is an approximation; cyan, magenta and yellow are the accurate subtractive set","Yellow is toxic","Paint ages"],"answer":1,"hint":"Historical artefact.","explanation":"The RYB wheel is a historical approximation; CMY is the accurate subtractive set.","level":2},
    {"id":"photo-art-school.ac-1.q3","lessonId":"ac-1","kind":"mcq","prompt":"What is a tone in the lesson vocabulary?","choices":["Hue plus grey","Pure hue","Hue plus white","Hue plus black"],"answer":0,"hint":"Not tint or shade.","explanation":"A tint adds white, a shade adds black, and a tone adds grey.","level":3},
    {"id":"photo-art-school.ac-2.q1","lessonId":"ac-2","kind":"mcq","prompt":"What proportion does the lesson give for dominant, subordinate and accent?","choices":["90/5/5","50/50/0","60/30/10","40/40/20"],"answer":2,"hint":"Roughly.","explanation":"The reliable proportion is about 60/30/10.","level":1},
    {"id":"photo-art-school.ac-2.q2","lessonId":"ac-2","kind":"mcq","prompt":"You want to neutralise a blue without using black. What does the lesson suggest?","choices":["Add a little red to push it towards a warmer purple","Add green","Add a touch of its complement, orange","Add more blue"],"answer":2,"hint":"Opposite on the wheel.","explanation":"Mixing complements neutralises a colour and gives living grey rather than dead grey.","level":2},
    {"id":"photo-art-school.ac-2.q3","lessonId":"ac-2","kind":"mcq","prompt":"Why is split-complementary reliable for beginners?","choices":["It has near the punch of complementary with less tension","It avoids hue contrast completely and relies on value alone","It needs no weighting","It uses one colour"],"answer":0,"hint":"Two colours adjacent to the complement.","explanation":"It gives nearly complementary contrast with less tension.","level":3},
    {"id":"photo-art-school.ac-3.q1","lessonId":"ac-3","kind":"mcq","prompt":"Who described simultaneous contrast systematically in 1839?","choices":["Leonardo da Vinci, in his notebooks","Georges Seurat, the Pointillist painter","Josef Albers, in his Bauhaus course","Michel Eugene Chevreul"],"answer":3,"hint":"Dyers complained about black yarns.","explanation":"Chevreul described it after dyers complained about black yarns next to blue.","level":1},
    {"id":"photo-art-school.ac-3.q2","lessonId":"ac-3","kind":"mcq","prompt":"A neutral grey surrounded by red appears what?","choices":["Redder","Greenish","Darker only","Unchanged"],"answer":1,"hint":"The eye induces the complement.","explanation":"The eye induces the complement, so grey appears greenish.","level":2},
    {"id":"photo-art-school.ac-3.q3","lessonId":"ac-3","kind":"mcq","prompt":"What practical conclusion did Albers draw?","choices":["Colour is fixed and looks the same wherever it is placed","Never choose a colour in isolation; judge it in place","Use swatches","Avoid colour"],"answer":1,"hint":"Interaction of Color.","explanation":"Colour must be judged against actual neighbours at its actual size.","level":3},
    {"id":"photo-art-school.ac-4.q1","lessonId":"ac-4","kind":"mcq","prompt":"Why was ultramarine used for the Virgin robe?","choices":["It was easy to mix from common earth pigments found locally","It was invented in 1826","It was cheap","It came from lapis lazuli and cost more than gold"],"answer":3,"hint":"Display of expense.","explanation":"Ultramarine was ground from lapis lazuli and was more costly than gold.","level":1},
    {"id":"photo-art-school.ac-4.q2","lessonId":"ac-4","kind":"mcq","prompt":"Which inventions did Impressionism depend on, per the lesson?","choices":["Synthetic pigments and the collapsible metal paint tube","Oil and egg tempera, brought in from the earlier Renaissance era","Acrylic and spray","Photography and film"],"answer":0,"hint":"Renoir quote.","explanation":"The lesson cites synthetic pigments and the paint tube patented in 1841.","level":2},
    {"id":"photo-art-school.ac-4.q3","lessonId":"ac-4","kind":"mcq","prompt":"What is happening to Van Gogh sunflowers?","choices":["Peeling only, as the paint lifts from the canvas","Blueing, as the yellow turns cool with age","Browning as chrome yellow degrades","Brightening, as the varnish slowly wears away"],"answer":2,"hint":"Fugitive pigment.","explanation":"Chrome yellow degrades, causing browning.","level":3},
    {"id":"photo-art-school.ac-5.q1","lessonId":"ac-5","kind":"mcq","prompt":"Roughly how many colours do professionals typically use, per the lesson?","choices":["Two, one warm and one cool","A hundred or more in the studio","Forty from the full pigment range","Six to twelve"],"answer":3,"hint":"Fewer.","explanation":"Professionals typically use six to twelve colours.","level":1},
    {"id":"photo-art-school.ac-5.q2","lessonId":"ac-5","kind":"mcq","prompt":"What specific cause of mud does the lesson give?","choices":["Using large brushes that spread the paint too thinly across the surface","Mixing three or more pigments, especially across the wheel","Using white","Thin paint"],"answer":1,"hint":"Drags toward neutral.","explanation":"Mixing three or more pigments pulls everything toward neutral.","level":2},
    {"id":"photo-art-school.ac-5.q3","lessonId":"ac-5","kind":"mcq","prompt":"Why does a limited palette guarantee harmony?","choices":["Every mixture shares parent pigments","Colours are cheaper","Mixtures are brighter","It avoids black"],"answer":0,"hint":"Shared parents.","explanation":"All mixtures derive from the same few pigments, creating coherence.","level":3},
    {"id":"photo-art-school.ac-6.q1","lessonId":"ac-6","kind":"mcq","prompt":"Which group used colour untethered from description around 1905?","choices":["The Pre-Raphaelites","The Impressionists","The Fauves","The Cubists"],"answer":2,"hint":"Wild beasts.","explanation":"The Fauves, including Matisse and Derain, were named wild beasts for their colour.","level":1},
    {"id":"photo-art-school.ac-6.q2","lessonId":"ac-6","kind":"mcq","prompt":"Rothko described his subject as what?","choices":["Geometry and pure mathematical order","Decoration and pleasing interior colour","Tragedy and ecstasy","Landscape and the colours of nature"],"answer":2,"hint":"Emotional and near-religious.","explanation":"Rothko said his subject was tragedy and ecstasy, not decoration.","level":2},
    {"id":"photo-art-school.ac-6.q3","lessonId":"ac-6","kind":"mcq","prompt":"What three jobs can colour do, per the lesson?","choices":["Describe, structure, signify","Warm, cool and neutral, as temperature roles","Hue, value and chroma, as its three qualities","Mix, blend and glaze, as painting techniques"],"answer":0,"hint":"What is this colour doing?","explanation":"Colour describes, structures or signifies; otherwise it is decoration.","level":3},
    {"id":"photo-art-school.ah-1.q1","lessonId":"ah-1","kind":"mcq","prompt":"Roughly how old are the oldest known figurative paintings mentioned in the lesson?","choices":["About 100,000 years","About 4,000 years","About 10,000 years","About 40,000 years"],"answer":3,"hint":"Sulawesi and El Castillo.","explanation":"The lesson dates the oldest known figurative paintings to around 40,000 years ago.","level":1},
    {"id":"photo-art-school.ah-1.q2","lessonId":"ah-1","kind":"mcq","prompt":"Why do Egyptian figures combine a profile head with frontal eye and shoulders?","choices":["Artists could not draw otherwise","Each part is shown from its most identifiable angle for functional afterlife images","It was a fashion","It saved paint"],"answer":1,"hint":"Not optical records.","explanation":"The composite view shows each part at its most identifiable angle because the images were functional equipment for the afterlife.","level":2},
    {"id":"photo-art-school.ah-1.q3","lessonId":"ah-1","kind":"mcq","prompt":"What does the lesson take from the Chauvet and Lascaux caves being deep and hard to reach?","choices":["They were galleries for visitors","They suggest ritual rather than display","They were storage","They were unfinished"],"answer":1,"hint":"Think purpose.","explanation":"Their location suggests ritual rather than casual viewing.","level":3},
    {"id":"photo-art-school.ah-2.q1","lessonId":"ah-2","kind":"mcq","prompt":"Which Greek figure first shows contrapposto, per the lesson?","choices":["Laocoon","The Winged Victory","A kouros","The Kritios Boy"],"answer":3,"hint":"Classical breakthrough.","explanation":"The Kritios Boy shows weight shifting to one leg, the Classical breakthrough.","level":1},
    {"id":"photo-art-school.ah-2.q2","lessonId":"ah-2","kind":"mcq","prompt":"A Roman republican bust shows wrinkles and jowls precisely. What is this called?","choices":["Verism","Mannerism","Archaism","Idealism"],"answer":0,"hint":"Age signalled authority.","explanation":"Verism records unflattering detail because age signalled authority in Rome.","level":2},
    {"id":"photo-art-school.ah-2.q3","lessonId":"ah-2","kind":"mcq","prompt":"What does the lesson say about the white marble aesthetic?","choices":["Romans removed colour","Marble was bleached","Greek sculpture was painted; the white look is an accident of lost pigment","Greeks preferred white"],"answer":2,"hint":"Lost pigment.","explanation":"Greek sculpture was painted and the white look comes from lost pigment.","level":3},
    {"id":"photo-art-school.ah-3.q1","lessonId":"ah-3","kind":"mcq","prompt":"What does gold ground signify in a Byzantine icon?","choices":["A tabletop on which the figures stand","A display of the patron wealth and nothing more","An ordinary background colour of the sky","The absence of earthly space"],"answer":3,"hint":"Window onto the eternal.","explanation":"Gold ground is the absence of earthly space.","level":1},
    {"id":"photo-art-school.ah-3.q2","lessonId":"ah-3","kind":"mcq","prompt":"Which Gothic features let walls dissolve into stained glass?","choices":["Round arches and thick walls, as in the Romanesque style","Pointed arch, rib vault and flying buttress","Domes and columns","Post and lintel"],"answer":1,"hint":"Chartres.","explanation":"The pointed arch, rib vault and flying buttress allowed large windows.","level":2},
    {"id":"photo-art-school.ah-3.q3","lessonId":"ah-3","kind":"mcq","prompt":"Why does the lesson say to treat art history as plural?","choices":["The European narrative is only one thread among many traditions","Europe had no art worth studying before the Renaissance began in Italy","Surveys are accurate","Plural is easier"],"answer":0,"hint":"Parallel traditions.","explanation":"China, Islamic world, West Africa, Mesoamerica and others ran their own arcs.","level":3},
    {"id":"photo-art-school.ah-4.q1","lessonId":"ah-4","kind":"mcq","prompt":"What is the intellectual shift behind the Renaissance?","choices":["Industrialism","Romanticism","Humanism","Mysticism"],"answer":2,"hint":"Antiquity and the individual.","explanation":"Humanism renewed attention to antiquity, the individual and nature.","level":1},
    {"id":"photo-art-school.ah-4.q2","lessonId":"ah-4","kind":"mcq","prompt":"Which artist is associated with sfumato?","choices":["Michelangelo","Raphael","Leonardo","Botticelli"],"answer":2,"hint":"Smoky blending.","explanation":"Leonardo brings sfumato, scientific observation and psychological subtlety.","level":2},
    {"id":"photo-art-school.ah-4.q3","lessonId":"ah-4","kind":"mcq","prompt":"How did Netherlandish painters organise space compared with Italians?","choices":["By empirical observation and oil paint detail","By gold leaf","By collage","By mathematical construction and the geometry of linear perspective"],"answer":0,"hint":"Van Eyck.","explanation":"They used empirical observation and oil to render surface precisely.","level":3},
    {"id":"photo-art-school.ah-5.q1","lessonId":"ah-5","kind":"mcq","prompt":"Roughly when is Baroque dated in the lesson?","choices":["1800-1850","1900-1945","1400-1500","1600-1750"],"answer":3,"hint":"Counter-Reformation.","explanation":"The lesson dates Baroque to roughly 1600-1750.","level":1},
    {"id":"photo-art-school.ah-5.q2","lessonId":"ah-5","kind":"mcq","prompt":"Why did the Dutch Republic produce specialised genres like landscape and still life?","choices":["Church commissions dominated, so painters made large altarpieces","A wealthy merchant class bought pictures for their houses","The king demanded them","Guilds banned portraits"],"answer":1,"hint":"No church, no monarchy.","explanation":"Merchants created an art market driven by specialised genres.","level":2},
    {"id":"photo-art-school.ah-5.q3","lessonId":"ah-5","kind":"mcq","prompt":"What do skulls and wilting flowers in a Dutch still life signal?","choices":["Mourning for the artist, who had just lost a family member","Vanitas: reminders of mortality amid wealth","Decoration only","Botanical study"],"answer":1,"hint":"Pleasure and warning together.","explanation":"Vanitas still lifes combine displays of wealth with mortality reminders.","level":3},
    {"id":"photo-art-school.ah-6.q1","lessonId":"ah-6","kind":"mcq","prompt":"Which painting by David is described as severe and politically charged?","choices":["Raft of the Medusa","Third of May 1808","Liberty Leading the People","Oath of the Horatii"],"answer":3,"hint":"Neoclassicism.","explanation":"David Oath of the Horatii is the Neoclassical example in the lesson.","level":1},
    {"id":"photo-art-school.ah-6.q2","lessonId":"ah-6","kind":"mcq","prompt":"Courbet painted stone breakers at heroic scale. What claim did Realism make?","choices":["Ordinary contemporary life is a legitimate subject","Painting should be abstract and avoid recognisable subjects","Colour is pointless","Only kings are worth painting"],"answer":0,"hint":"Radical simplicity.","explanation":"Realism claimed ordinary life is legitimate and need not be idealised.","level":2},
    {"id":"photo-art-school.ah-6.q3","lessonId":"ah-6","kind":"mcq","prompt":"How did photography change painting, per the lesson?","choices":["It improved oil paint by supplying painters with sharper references","It made painting unnecessary","It made what painting is uniquely for an urgent question","It had no effect"],"answer":2,"hint":"Daguerre in 1839.","explanation":"Once appearance could be recorded cheaply, painting had to ask what it was uniquely for.","level":3},
    {"id":"photo-art-school.ah-7.q1","lessonId":"ah-7","kind":"mcq","prompt":"In what year did the Impressionists hold their first independent exhibition?","choices":["1905","1913","1848","1874"],"answer":3,"hint":"After Salon rejection.","explanation":"The first independent exhibition was in 1874.","level":1},
    {"id":"photo-art-school.ah-7.q2","lessonId":"ah-7","kind":"mcq","prompt":"Which inventions enabled painting outdoors and quickly?","choices":["Folding easels and long-handled wooden palettes","Paint tubes and synthetic pigments","Cameras only, used to record each outdoor scene","Acrylics, which dry faster than oil paint"],"answer":1,"hint":"Material side.","explanation":"Paint tubes and synthetic pigments made outdoor painting practical.","level":2},
    {"id":"photo-art-school.ah-7.q3","lessonId":"ah-7","kind":"mcq","prompt":"Which Post-Impressionist laid the foundation for Cubism by building form from planes of colour?","choices":["Cezanne","Seurat","Van Gogh","Gauguin"],"answer":0,"hint":"Solid and durable.","explanation":"Cezanne built form from planes of colour, foundation for Cubism.","level":3},
    {"id":"photo-art-school.ah-8.q1","lessonId":"ah-8","kind":"mcq","prompt":"Which movement began around 1907 with Picasso and Braque?","choices":["Dada","Fauvism","Cubism","Futurism"],"answer":2,"hint":"The hinge.","explanation":"Cubism, from 1907, dismantled single-viewpoint perspective.","level":1},
    {"id":"photo-art-school.ah-8.q2","lessonId":"ah-8","kind":"mcq","prompt":"What did Duchamp readymades relocate art from and to?","choices":["From paint to bronze, as a change of material","From Paris to Berlin, as a change of city","From craft to concept","From colour to line, as a change of focus"],"answer":2,"hint":"Dada.","explanation":"Readymades move art from craft to concept.","level":2},
    {"id":"photo-art-school.ah-8.q3","lessonId":"ah-8","kind":"mcq","prompt":"What does the 1937 Degenerate Art exhibition show, per the lesson?","choices":["Formal arguments were never only formal","Art is neutral","Modernism ended","Bauhaus opened"],"answer":0,"hint":"Politics.","explanation":"The lesson says it makes explicit that these formal arguments were never only formal.","level":3},
    {"id":"photo-art-school.ah-9.q1","lessonId":"ah-9","kind":"mcq","prompt":"Which city became the centre after the war with Abstract Expressionism?","choices":["Berlin, which had led before the war","Paris, which had led before the war","London, as the capital of the postwar market","New York"],"answer":3,"hint":"Scattered artists.","explanation":"Abstract Expressionism made New York the centre.","level":1},
    {"id":"photo-art-school.ah-9.q2","lessonId":"ah-9","kind":"mcq","prompt":"What do Sol LeWitt wall drawings exemplify?","choices":["Pop art, which borrowed its images from consumer advertising","Conceptual art where instructions are the art","Land Art","Abstract Expressionism"],"answer":1,"hint":"Idea is the art.","explanation":"LeWitt wall drawings are instructions, illustrating conceptual art.","level":2},
    {"id":"photo-art-school.ah-9.q3","lessonId":"ah-9","kind":"mcq","prompt":"What is the actual content of postmodernism, per the lesson?","choices":["Minimalism","A single narrative breaking apart into pluralism and challenge to whose history was written","A return to realism","Pure abstraction"],"answer":1,"hint":"From the 1970s.","explanation":"It is pluralism, appropriation, irony, institutional critique and challenging the canon.","level":3},
    {"id":"photo-art-school.ah-10.q1","lessonId":"ah-10","kind":"mcq","prompt":"What year did Daguerre announce the daguerreotype?","choices":["1859","1888","1900","1839"],"answer":3,"hint":"Same year as Talbot.","explanation":"Daguerre and Talbot announced their processes in 1839.","level":1},
    {"id":"photo-art-school.ah-10.q2","lessonId":"ah-10","kind":"mcq","prompt":"Why did Talbot negative-positive process matter for mass media?","choices":["Reproducibility","Colour, as the first full-colour process","Size, since it gave larger images","It produced finer detail than a daguerreotype"],"answer":0,"hint":"Many prints.","explanation":"Negatives allow reproducibility, making photography a mass medium.","level":2},
    {"id":"photo-art-school.ah-10.q3","lessonId":"ah-10","kind":"mcq","prompt":"What does the lesson say of the age of billions of images?","choices":["Photography ends","Craft is devalued","Intention becomes the scarce commodity","Film returns"],"answer":2,"hint":"Trillions of images.","explanation":"Craft is not devalued; intention becomes scarce.","level":3},
    {"id":"photo-art-school.ak-1.q1","lessonId":"ak-1","kind":"mcq","prompt":"About how long does the average museum visitor look at a painting, per the lesson?","choices":["Ten minutes, enough for a careful look","One hour, including time to read labels","Two minutes, long enough to read the label","Seventeen seconds"],"answer":3,"hint":"Including reading the label.","explanation":"The lesson cites about fifteen to thirty seconds, roughly seventeen on average.","level":1},
    {"id":"photo-art-school.ak-1.q2","lessonId":"ak-1","kind":"mcq","prompt":"When should you read the wall label in the slow looking exercise?","choices":["Before looking, to learn what to expect","After looking for ten minutes","Never, because labels spoil the experience","During minute one, to orient yourself first"],"answer":1,"hint":"Order matters.","explanation":"Labels shortcut you into someone else reading, so read after your own.","level":2},
    {"id":"photo-art-school.ak-1.q3","lessonId":"ak-1","kind":"mcq","prompt":"Why is the first two minutes of slow looking uncomfortable?","choices":["You feel you have already seen it","The art is simply boring at first sight","The light in most galleries is poor","You need a guide to explain the piece"],"answer":0,"hint":"Then you notice more.","explanation":"You feel you have seen it, but around minute three you notice what you missed.","level":3},
    {"id":"photo-art-school.ak-2.q1","lessonId":"ak-2","kind":"mcq","prompt":"What is formal analysis?","choices":["Researching the biography of the artist who made the work","Valuation","Disciplined description of visual properties","Guessing intent"],"answer":2,"hint":"Before meaning.","explanation":"It describes composition, line, value, colour and so on.","level":1},
    {"id":"photo-art-school.ak-2.q2","lessonId":"ak-2","kind":"mcq","prompt":"Which statement is precise enough for formal analysis?","choices":["It is moving","The colours are nice","The palette is earth tones except a single vermilion sleeve at the centre, the lightest value","It is beautiful"],"answer":2,"hint":"Specific.","explanation":"Precise statements tell what the artist did.","level":2},
    {"id":"photo-art-school.ak-2.q3","lessonId":"ak-2","kind":"mcq","prompt":"What is the test of a good formal analysis?","choices":["A reader who never saw the work could sketch a rough version","It is long, covering every detail of the work and the artist life","It uses jargon","It includes biography"],"answer":0,"hint":"Sketch.","explanation":"The description should be enough to sketch the work.","level":3},
    {"id":"photo-art-school.ak-3.q1","lessonId":"ak-3","kind":"mcq","prompt":"Who gave the three-level model of iconography?","choices":["Greenberg","Nochlin","Berger","Panofsky"],"answer":3,"hint":"Erwin.","explanation":"Erwin Panofsky gave the standard model.","level":1},
    {"id":"photo-art-school.ak-3.q2","lessonId":"ak-3","kind":"mcq","prompt":"Seeing a woman in blue, a lily and a kneeling winged figure and concluding Annunciation is which level?","choices":["Pre-iconographic","Iconographical analysis","Iconological interpretation","Formal"],"answer":1,"hint":"Conventional signification.","explanation":"Level two identifies conventional meaning, the lily as purity and Gabriel.","level":2},
    {"id":"photo-art-school.ak-3.q3","lessonId":"ak-3","kind":"mcq","prompt":"What failure does the lesson warn about?","choices":["Taking notes on every detail of the work as you look","Assuming symbols mean what they would today","Looking too long","Reading the label"],"answer":1,"hint":"Audience then.","explanation":"Symbols must be read as the original audience did.","level":3},
    {"id":"photo-art-school.ak-4.q1","lessonId":"ak-4","kind":"mcq","prompt":"What does formalism treat as irrelevant?","choices":["Colour","Line","Composition","Context"],"answer":3,"hint":"Greenberg.","explanation":"Formalism attends only to visual properties.","level":1},
    {"id":"photo-art-school.ak-4.q2","lessonId":"ak-4","kind":"mcq","prompt":"Which lens explains why Dutch merchants bought still lifes?","choices":["Marxist and social-historical","Biographical, focused on the artist life","Formalist, focused on visual structure","Psychoanalytic, focused on hidden desire"],"answer":0,"hint":"Patronage and class.","explanation":"Social-historical criticism explains patronage and subject.","level":2},
    {"id":"photo-art-school.ak-4.q3","lessonId":"ak-4","kind":"mcq","prompt":"What does Nochlin essay answer by examining institutional exclusion?","choices":["Who first invented linear perspective in Florence","Why Dutch art flourished in the seventeenth century","Why great women artists were rare","What the male gaze means in film"],"answer":2,"hint":"Not talent.","explanation":"She argued that exclusion, not talent, explains it.","level":3},
    {"id":"photo-art-school.ak-5.q1","lessonId":"ak-5","kind":"mcq","prompt":"What four steps does Feldman propose?","choices":["Look, like, buy and sell, as in a market","Sketch, paint, frame and hang, as in a studio","Read, copy, compare and rank, as in a classroom","Describe, analyse, interpret, judge"],"answer":3,"hint":"Judgment last.","explanation":"Describe, analyse, interpret, then judge.","level":1},
    {"id":"photo-art-school.ak-5.q2","lessonId":"ak-5","kind":"mcq","prompt":"Which statement is a defensible judgment?","choices":["I do not like it","This fails because it has three competing focal points and no narrative centre","It is famous","My child could do that"],"answer":1,"hint":"Follows from analysis.","explanation":"It is a claim about the work that can be disputed.","level":2},
    {"id":"photo-art-school.ak-5.q3","lessonId":"ak-5","kind":"mcq","prompt":"Why is deferring to the canon a failure mode?","choices":["It is a set of revisable past judgments by particular people","The canon is wrong in nearly every judgement it has ever made","Canon is new","It is illegal"],"answer":0,"hint":"Revisable.","explanation":"The canon was made by people with interests and can be revised.","level":3},
    {"id":"photo-art-school.ak-6.q1","lessonId":"ak-6","kind":"mcq","prompt":"About how long should an artist statement be, per the lesson?","choices":["Five pages, to cover the whole career","Ten words, to stay as brief as possible","150 to 300 words","2000 words, to cover all the ideas"],"answer":2,"hint":"Short.","explanation":"About 150 to 300 words in plain language.","level":1},
    {"id":"photo-art-school.ak-6.q2","lessonId":"ak-6","kind":"mcq","prompt":"Which critique comment follows the lesson advice?","choices":["It lacks something important, though it is hard to say what","The composition is off","The eye goes to the bright corner instead of the face","I love it"],"answer":2,"hint":"Concrete.","explanation":"It names what is physically present and its effect.","level":2},
    {"id":"photo-art-school.ak-6.q3","lessonId":"ak-6","kind":"mcq","prompt":"How should you receive critique?","choices":["Take notes, thank people, decide later","Explain what you meant","Ignore it","Defend each point"],"answer":0,"hint":"Misreading is information.","explanation":"Do not explain during feedback; sort what to act on later.","level":3},
  ],
};
